1	// Install a finished Cyrus / Mod Builder build onto one of the user's Minecraft servers.
2	//
3	// Since 2026-10-07 (Cyrus mods) this goes THROUGH THE MODS ENGINE instead of a
4	// direct copy: the build's chain gets a GameMod row (source "cyrus",
5	// lib/cyrus-mods/registry.ts), the ServerMod row is queued INSTALLING/UPDATING
6	// with targetVersionId = this build, and the worker's GAME_MOD_SYNC places the
7	// jar with lib/mods/engine.ts (state file, backup, staged write, rollback). So
8	// the Mods tab lists it, can switch it off/on, update it, roll it back and
9	// uninstall it like any other plugin.
10	//
11	// A jar a PRE-ENGINE builder install left in plugins/ (not in the engine's state
12	// file) is backed up to /root/.nxeon-mods/backups/<stamp>-cyrus-adopt-<name>/
13	// and removed first, so the server never loads two copies of one plugin.
14	// The route then waits briefly for the job so the Cyrus UI can say "done".
15	import { flightBlocks } from "../cyrus/testflight/gate";
16	import type { ModBuild } from "@prisma/client";
17	import { enqueueModOp } from "../mods/queue";
18	import { loadState, ownerOf } from "../mods/engine";
19	import { ensureCyrusGameMod, loadChain, rootOf } from "../cyrus-mods/registry";
20	import { syncCyrusModPage } from "../cyrus-mods/pages";
21	import { db } from "../db";
22	import { SANDBOX } from "../sandbox";
23	import { familyFor } from "../game-config";
24	import { LocalGuestFs, sandboxGuestRoot, seedSandboxGuest, type GuestFs } from "../mods/guest-fs";
25	import { SshGuestFs } from "../../worker/mods-guest-ssh";
26	import { cyrusConfig } from "../cyrus/config";
27	
28	const MC_BASE = cyrusConfig().guest.mcBase;
29	const PLUGINS = `${MC_BASE}/plugins`;
30	const BACKUPS = cyrusConfig().guest.modsBackupDir;
31	/** Generated plugins target the Paper API (Adventure etc.), so Spigot/Bukkit can't load them, and they aren't Folia-safe. */
32	export const MB_INSTALL_VARIANTS = ["paper", "purpur"];
33	
34	import type { MbServer } from "../cyrus/builder/types";
35	export type { MbServer };
36	
37	/** The user's Minecraft servers, each marked whether a builder plugin can go on it. */
38	export async function modBuilderServers(userId: string): Promise<MbServer[]> {
39	  const rows = await db.server.findMany({
40	    where: { userId, status: { notIn: ["DELETING"] } },
41	    include: { osTemplate: true, gamePlan: true },
42	    orderBy: { createdAt: "asc" },
43	  });
44	  const out: MbServer[] = [];
45	  for (const s of rows) {
46	    if (familyFor(s) !== "minecraft") continue;
47	    const variant = (s.gameVariant || "vanilla").toLowerCase();
48	    const okVariant = MB_INSTALL_VARIANTS.includes(variant);
49	    // The engine installs onto the running server (same rule as the Mods tab).
50	    const okStatus = s.status === "RUNNING";
51	    out.push({
52	      id: s.id,
53	      name: s.label || s.hostname,
54	      variant,
55	      status: s.status,
56	      compatible: okVariant && okStatus,
57	      reason: !okVariant ? `Runs ${variant[0].toUpperCase() + variant.slice(1)}; plugins need Paper or Purpur` : !okStatus ? (s.status === "STOPPED" ? "Server is stopped — start it to install" : `Server is ${s.status.toLowerCase()}`) : undefined,
58	    });
59	  }
60	  return out;
61	}
62	
63	function stamp(d = new Date()) {
64	  return d.toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "-");
65	}
66	
67	export type InstallResult =
68	  | { ok: true; path: string; replaced: string[]; backupDir: string | null; serverName: string; queued: boolean; jobId: string; modId: string }
69	  | { ok: false; error: string };
70	
71	/**
72	 * Move aside jars an older (pre-engine) builder install left in plugins/: only
73	 * files the engine's state file does NOT own, named like this plugin. Backed up
74	 * first. Returns what was moved.
75	 */
76	async function adoptLegacyJars(server: Parameters<typeof SshGuestFs.open>[0] & { id: string; gameVariant: string | null }, chain: ModBuild[]): Promise<{ moved: string[]; backupDir: string | null }> {
77	  let fs: GuestFs;
78	  let ssh: SshGuestFs | null = null;
79	  try {
80	    if (SANDBOX) {
81	      const local = new LocalGuestFs(sandboxGuestRoot(server.id));
82	      await seedSandboxGuest(local, "minecraft", server.gameVariant ?? null);
83	      fs = local;
84	    } else {
85	      ssh = await SshGuestFs.open(server);
86	      fs = ssh;
87	    }
88	    if (!(await fs.stat(PLUGINS))) return { moved: [], backupDir: null };
89	    const state = await loadState(fs, "minecraft");
90	    const names = new Set(chain.map((b) => (b.pluginName ?? "").toLowerCase()).filter(Boolean));
91	    const jars = new Set(chain.map((b) => (b.jarName ?? "").toLowerCase()).filter(Boolean));
92	    const legacy = (await fs.list(PLUGINS)).filter((f) => {
93	      const l = f.toLowerCase();
94	      if (!l.endsWith(".jar") || ownerOf(state, `${PLUGINS}/${f}`)) return false;
95	      return jars.has(l) || [...names].some((n) => l === `${n}.jar` || (l.startsWith(`${n}-`) && /^[0-9]/.test(l.slice(n.length + 1))));
96	    });
97	    if (!legacy.length) return { moved: [], backupDir: null };
98	    const label = (chain[0].pluginName ?? "plugin").replace(/[^A-Za-z0-9_]/g, "") || "plugin";
99	    const backupDir = `${BACKUPS}/${stamp()}-cyrus-adopt-${label}`;
100	    for (const f of legacy) await fs.copy(`${PLUGINS}/${f}`, `${backupDir}${PLUGINS}/${f}`);
101	    for (const f of legacy) await fs.remove(`${PLUGINS}/${f}`);
102	    return { moved: legacy, backupDir };
103	  } finally {
104	    ssh?.close();
105	  }
106	}
107	
108	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
109	
110	/** The checks every install path shares (installBuildToServer and the Cyrus delivery enqueue, lib/modbuilder/delivery.ts). */
111	export async function installEligibility(build: ModBuild, userId: string, serverId: string, opts: { allowPublic?: boolean } = {}) {
112	  // allowPublic (Cyrus lifecycle): install a PUBLISHED version of another creator's mod from NxLabs.
113	  const own = build.userId === userId;
114	  if (!own && !(opts.allowPublic && (await (await import("../cyrus/lifecycle/server")).publicInstallAllowed(build, userId)))) return { ok: false as const, error: "Not found." };
115	  if (build.status !== "succeeded" || !build.jarName || !build.pluginName) return { ok: false as const, error: "This build has no plugin file to install." };
116	  const fb = flightBlocks((build.cyrus as { testFlight?: unknown } | null)?.testFlight); // Cyrus R5 optional gate
117	  if (fb.blocked) return { ok: false as const, error: fb.reason };
118	  const server = await db.server.findUnique({ where: { id: serverId }, include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true } });
119	  if (!server || server.userId !== userId) return { ok: false as const, error: "Server not found." };
120	  const servers = await modBuilderServers(userId);
121	  const facts = servers.find((s) => s.id === serverId);
122	  if (!facts) return { ok: false as const, error: "That server isn't a Minecraft server." };
123	  if (!facts.compatible) return { ok: false as const, error: facts.reason || "That server can't take this plugin." };
124	  if (!SANDBOX && process.env.ENABLE_REAL_GAMEMODS !== "1") return { ok: false as const, error: "One-click mod changes are paused right now, so nothing was installed." };
125	  return { ok: true as const, own, server, facts };
126	}
127	
128	export async function installBuildToServer(build: ModBuild, userId: string, serverId: string, opts: { waitMs?: number; allowPublic?: boolean } = {}): Promise<InstallResult> {
129	  const el = await installEligibility(build, userId, serverId, opts);
130	  if (!el.ok) return el;
131	  const { own, server, facts } = el;
132	
133	  const root = rootOf(build);
134	  const chain = await loadChain(root);
135	  await syncCyrusModPage(root);
136	  const gm = await ensureCyrusGameMod(root, chain);
137	  if (!gm) return { ok: false, error: "This build has no plugin file to install." };
138	
139	  const existing = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId: gm.id } } });
140	  if (existing?.status === "DISABLED") return { ok: false, error: `${gm.name} is switched off on ${facts.name}. Switch it on in the server's Mods tab first, then install this version.` };
141	  if (existing && !["INSTALLED", "FAILED", "REMOVED"].includes(existing.status)) return { ok: false, error: `${gm.name} is busy on that server (${existing.status.toLowerCase()}). Try again in a moment.` };
142	  if (existing?.status === "INSTALLED" && existing.versionId === build.id) {
143	    return { ok: true, path: `${PLUGINS}/${build.jarName}`, replaced: [], backupDir: null, serverName: facts.name, queued: false, jobId: "", modId: gm.id };
144	  }
145	  const op = existing?.status === "INSTALLED" ? "update" : "install";
146	
147	  // First engine install on a server an older builder install already used: adopt its jar.
148	  let adopted: { moved: string[]; backupDir: string | null } = { moved: [], backupDir: null };
149	  const touched = own && chain.some((b) => (b.lastInstall as { serverId?: string } | null)?.serverId === serverId);
150	  if (op === "install" && touched) {
151	    try {
152	      adopted = await adoptLegacyJars(server, chain);
153	    } catch (e) {
154	      console.error("[modbuilder] legacy adopt failed", build.id, serverId, (e as Error).message);
155	      return { ok: false, error: "We couldn't reach the server to check its plugins folder. Check it's online and try again." };
156	    }
157	  }
158	
159	  const prevVersion = existing?.status === "INSTALLED" ? existing.version : null;
160	  const q = await enqueueModOp(serverId, gm.id, op, { userId, slug: gm.slug }, { targetVersionId: build.id });
161	  if (!q.ok) return { ok: false, error: q.error };
162	
163	  // Wait (briefly) for the worker so the builder UI can report the outcome.
164	  const deadline = Date.now() + (opts.waitMs ?? 45_000);
165	  while (Date.now() < deadline) {
166	    await sleep(1000);
167	    const job = await db.job.findUnique({ where: { id: q.jobId }, select: { status: true, error: true } });
168	    if (!job || job.status === "QUEUED" || job.status === "RUNNING") continue;
169	    const sm = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId: gm.id } } });
170	    if (job.status === "FAILED") return { ok: false, error: sm?.error || "The install job failed. Check the server's Mods tab." };
171	    if (!sm || sm.status === "FAILED" || sm.versionId !== build.id) return { ok: false, error: sm?.error || "The plugin wasn't installed. Check the server's Mods tab." };
172	    return {
173	      ok: true,
174	      path: `${PLUGINS}/${build.jarName}`,
175	      replaced: [...adopted.moved, ...(prevVersion ? [`${gm.name} ${prevVersion}`] : [])],
176	      backupDir: adopted.backupDir,
177	      serverName: facts.name,
178	      queued: false,
179	      jobId: q.jobId,
180	      modId: gm.id,
181	    };
182	  }
183	  return { ok: true, path: `${PLUGINS}/${build.jarName}`, replaced: adopted.moved, backupDir: adopted.backupDir, serverName: facts.name, queued: true, jobId: q.jobId, modId: gm.id };
184	}
