1	/**
2	 * Queue a mod change for the worker: flip the ServerMod row to its pending
3	 * status and create ONE GAME_MOD_SYNC job, check-then-enqueue under the
4	 * per-server advisory lock (lib/job-guard.ts) so two clicks can't queue two
5	 * jobs or race a power/backup job. The worker (worker/game-mods.ts) is the
6	 * only thing that touches the server.
7	 */
8	import { db } from "../db";
9	import { withServerJobLock } from "../job-guard";
10	import { OP_FROM as FROM, OP_TO as TO_STATUS, validateBatch, type BatchOp } from "./batch";
11	
12	export type ModOp = "install" | "remove" | "update" | "disable" | "enable";
13	
14	export async function enqueueModOp(
15	  serverId: string,
16	  modId: string,
17	  op: ModOp,
18	  audit: { userId: string; slug: string },
19	  /** Cyrus update/rollback: the exact version the worker must place (ServerMod.targetVersionId).
20	   *  restartAfter (Cyrus perf safety): the worker restarts the game once the change is applied, so a plugin that is
21	   *  dragging the server down is really unloaded (used by "Disable this mod now" and the post-install perf watch). */
22	  opts?: { targetVersionId?: string | null; restartAfter?: boolean },
23	): Promise<{ ok: true; jobId: string } | { ok: false; error: string }> {
24	  const target = opts?.targetVersionId ?? null;
25	  const r = await withServerJobLock(serverId, async (tx) => {
26	    const inflight = await tx.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
27	    if (inflight > 0) return { ok: false as const, error: "Another operation is already running on this server — try again when it finishes." };
28	    const existing = await tx.serverMod.findUnique({ where: { serverId_modId: { serverId, modId } } });
29	    const cur = existing?.status ?? null;
30	    if (!FROM[op].includes(cur)) {
31	      const msg =
32	        op === "install" && (cur === "INSTALLED" || cur === "DISABLED") ? "That mod is already installed."
33	        : cur === null ? "That mod isn't installed."
34	        : `That mod is ${cur.toLowerCase()} — it can't be ${op === "remove" ? "removed" : op + "d"} right now.`;
35	      return { ok: false as const, error: msg };
36	    }
37	    await tx.serverMod.upsert({
38	      where: { serverId_modId: { serverId, modId } },
39	      create: { serverId, modId, status: TO_STATUS[op], error: null, targetVersionId: target },
40	      update: { status: TO_STATUS[op], error: null, targetVersionId: target },
41	    });
42	    const job = await tx.job.create({ data: { type: "GAME_MOD_SYNC", serverId, payload: { op, modId, ...(target ? { targetVersionId: target } : {}), ...(opts?.restartAfter ? { restartAfter: true } : {}) } }, select: { id: true } });
43	    return { ok: true as const, jobId: job.id };
44	  });
45	  if (r.ok) {
46	    await db.auditLog
47	      .create({ data: { userId: audit.userId, action: `gameserver.mod.${op}`, detail: `${serverId} mod=${audit.slug}${target ? ` version=${target}` : ""}` } })
48	      .catch(() => {});
49	  }
50	  return r;
51	}
52	
53	/**
54	 * Several changes (toggles / removals) in ONE job, applied by the worker in
55	 * the given order. All-or-nothing at enqueue: if any row can't start, nothing
56	 * is queued. Each change gets its own AuditLog row.
57	 */
58	export async function enqueueModBatch(
59	  serverId: string,
60	  ops: BatchOp[],
61	  audit: { userId: string; slugs: Map<string, string>; detail?: string },
62	): Promise<{ ok: true; jobId: string } | { ok: false; error: string }> {
63	  const r = await withServerJobLock(serverId, async (tx) => {
64	    const inflight = await tx.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
65	    if (inflight > 0) return { ok: false as const, error: "Another operation is already running on this server — try again when it finishes." };
66	    const rows = await tx.serverMod.findMany({ where: { serverId, modId: { in: ops.map((o) => o.modId) } }, select: { modId: true, status: true } });
67	    const err = validateBatch(ops, new Map(rows.map((x) => [x.modId, x.status])), audit.slugs);
68	    if (err) return { ok: false as const, error: err };
69	    for (const o of ops) {
70	      await tx.serverMod.update({ where: { serverId_modId: { serverId, modId: o.modId } }, data: { status: TO_STATUS[o.op], error: null } });
71	    }
72	    const job = await tx.job.create({ data: { type: "GAME_MOD_SYNC", serverId, payload: { ops: ops.map((o) => ({ modId: o.modId, op: o.op })), batch: true } }, select: { id: true } });
73	    return { ok: true as const, jobId: job.id };
74	  });
75	  if (r.ok) {
76	    await db.auditLog
77	      .createMany({ data: ops.map((o) => ({ userId: audit.userId, action: `gameserver.mod.${o.op}`, detail: `${serverId} mod=${audit.slugs.get(o.modId) ?? o.modId} batch=${r.jobId}${audit.detail ? " " + audit.detail : ""}`.slice(0, 900) })) })
78	      .catch(() => {});
79	  }
80	  return r;
81	}
