1	/**
2	 * Cyrus mods through the shared mods engine (source "cyrus").
3	 *
4	 * A Cyrus mod is a Paper plugin jar built by Cyrus (ModBuild, jar stored on the
5	 * primary under /var/lib/nxeon/modbuilds). Routing its installs through
6	 * lib/mods/engine.ts — instead of the old direct copy — means the guest state
7	 * file records exactly which jar Nxeon placed, so the Mods tab can list it,
8	 * switch it off/on, update it, roll it back and uninstall it like any
9	 * catalogue plugin (backups, staged write, rollback included).
10	 *
11	 * GameMod row: gameFamily "minecraft", source "cyrus", sourceId = the chain's
12	 * rootBuildId, active=false (never listed in the catalogue/store), created by
13	 * lib/cyrus-mods/registry.ts. The version placed is CatalogFacts.targetVersionId
14	 * (a ModBuild id, for update/rollback), else the chain's current version.
15	 *
16	 * The jar never leaves the primary over the network: it is read from disk and
17	 * handed to the engine as a prefetched package (sha256 checked against the
18	 * stored ModBuild.jarSha256).
19	 */
20	import { createHash } from "node:crypto";
21	import type { CatalogFacts, InstallerCtx, Resolution } from "../types";
22	
23	// Owned by Cyrus (lib/cyrus/source.ts); re-exported so the platform keeps importing them from here.
24	import { CYRUS_SOURCE, CYRUS_VARIANTS } from "../../cyrus/source";
25	export { CYRUS_SOURCE, CYRUS_VARIANTS };
26	
27	export type CyrusJar = {
28	  build: { id: string; version: string | null; pluginName: string | null; jarName: string; jarSha256: string | null; mcVersion: string };
29	  /** Display name of the mod (page title). */
30	  name: string;
31	  /** Unique package version within the chain (version string, disambiguated when two versions share one). */
32	  packageVersion: string;
33	  bytes: Buffer;
34	};
35	
36	/** Where jars come from. Default: the DB + jar store (./../../cyrus-mods/registry). Tests swap it. */
37	export type CyrusJarSource = (args: { rootBuildId: string; targetBuildId: string | null; serverId: string }) => Promise<CyrusJar | { error: string }>;
38	
39	let source: CyrusJarSource | null = null;
40	export function setCyrusJarSource(fn: CyrusJarSource | null) {
41	  source = fn;
42	}
43	async function jarSource(): Promise<CyrusJarSource> {
44	  if (source) return source;
45	  const m = await import("../../cyrus-mods/registry");
46	  return m.loadCyrusJar;
47	}
48	
49	/** plugins/<Name>/ folder name for a plugin name (null when nothing safe is left: never back up plugins/ itself). */
50	export function configDir(pluginName: string | null): string | null {
51	  const n = (pluginName ?? "").replace(/[^A-Za-z0-9_-]/g, "");
52	  return n.length ? n : null;
53	}
54	
55	export const cyrusPackageKey = (rootBuildId: string) => `cyrus:${rootBuildId}`;
56	
57	export async function resolveCyrus(mod: CatalogFacts, ctx: InstallerCtx): Promise<Resolution | { error: string }> {
58	  const variant = (ctx.server.variant ?? "vanilla").toLowerCase();
59	  if (!CYRUS_VARIANTS.includes(variant)) return { error: `Cyrus mods are Paper plugins — this server runs ${variant}. Switch it to Paper or Purpur in Settings first.` };
60	  if (!mod.sourceId) return { error: "This Cyrus mod has no build history to install from." };
61	  const got = await (await jarSource())({ rootBuildId: mod.sourceId, targetBuildId: mod.targetVersionId ?? null, serverId: ctx.server.id });
62	  if ("error" in got) return got;
63	  const sha = createHash("sha256").update(got.bytes).digest("hex");
64	  if (got.build.jarSha256 && got.build.jarSha256 !== sha) return { error: "The stored plugin file doesn't match its checksum — nothing was installed. Rebuild it in Cyrus." };
65	  const notes: string[] = [];
66	  if (ctx.layout.gameVersion && got.build.mcVersion && ctx.layout.gameVersion !== got.build.mcVersion) {
67	    notes.push(`Built for Minecraft ${got.build.mcVersion}; your server runs ${ctx.layout.gameVersion}. Paper plugins usually carry across 1.21.x — check the console after the restart.`);
68	  }
69	  return {
70	    packages: [
71	      {
72	        key: cyrusPackageKey(mod.sourceId),
73	        name: got.name,
74	        version: got.packageVersion,
75	        versionId: got.build.id,
76	        file: { url: `cyrus://${got.build.id}`, filename: got.build.jarName, size: got.bytes.length, hashes: { sha256: sha } },
77	        placement: "plugin-jar",
78	        requires: [],
79	        incompatible: [],
80	        prefetched: got.bytes,
81	        root: true,
82	      },
83	    ],
84	    notes,
85	    // Keep a copy of the plugin's config folder (plugins/<Name>/) with the jar backup, so an
86	    // update or rollback can always be undone with the settings it had.
87	    ...(configDir(got.build.pluginName) && ctx.layout.dirs.plugins ? { alsoBackupDirs: [`${ctx.layout.dirs.plugins}/${configDir(got.build.pluginName)}`] } : {}),
88	  };
89	}
