1	/**
2	 * The install engine every lib/mods/installers/* family shares.
3	 *
4	 * It owns everything that must be the same for every game: the per-server
5	 * state file on the guest, dependency reference counting, conflict
6	 * detection, backups, staged writes with rollback, idempotent re-runs, and
7	 * enable/disable/update/uninstall. Installers only answer "where", "which
8	 * build" and "which files".
9	 *
10	 * STATE lives ON THE GUEST at /root/.nxeon-mods/state.json, not in our DB:
11	 * it is the record of which files Nxeon itself put on that disk, so it has to
12	 * travel with the disk (a restored backup, a customer who deleted things by
13	 * hand). The DB's ServerMod row stays the customer-facing desired state; the
14	 * worker reconciles the two. Nothing outside the state file is ever deleted.
15	 *
16	 * Concurrency: the worker never runs two jobs for the same server at once
17	 * (worker/index.ts lock key = serverId) and the portal refuses to queue a
18	 * second while one is in flight, so the state file has a single writer.
19	 */
20	import { createHash } from "node:crypto";
21	import type { GuestFs } from "./guest-fs";
22	import { isWithin } from "./paths";
23	import { FetchError, type Fetcher } from "./safe-fetch";
24	import type { MirrorLookup } from "./mirror";
25	import type { CatalogFacts, FamilyInstaller, InstallerCtx, Layout, OpResult, PlacedFile, ResolvedPackage, ServerFacts } from "./types";
26	
27	export const STATE_DIR = "/root/.nxeon-mods";
28	export const STATE_PATH = `${STATE_DIR}/state.json`;
29	const BACKUP_DIR = `${STATE_DIR}/backups`;
30	const DISABLED_DIR = `${STATE_DIR}/disabled`;
31	const KEEP_BACKUPS = 5;
32	/** Ceiling on what one operation may download in total (all packages). */
33	export const MAX_OP_BYTES = 512 * 1024 * 1024;
34	/** Ceiling on a single downloaded file. */
35	export const MAX_FILE_BYTES = 256 * 1024 * 1024;
36	
37	export type FileRec = { path: string; sha256: string; size: number };
38	export type PkgState = {
39	  key: string;
40	  name: string;
41	  version: string;
42	  versionId: string | null;
43	  files: FileRec[];
44	  /** GameMod ids that need this package (directly, or as a dependency). */
45	  roots: string[];
46	  requires: string[];
47	  incompatible: { key: string; name: string }[];
48	  disabled: boolean;
49	  installedAt: string;
50	  updatedAt: string;
51	};
