64	export async function loadState(fs: GuestFs, family: string): Promise<GuestState> {
65	  const raw = await fs.readFile(STATE_PATH, 8 * 1024 * 1024);
66	  if (!raw) return emptyState(family);
67	  try {
68	    const s = JSON.parse(raw.toString("utf8")) as GuestState;
69	    if (s && s.v === 1 && s.packages && s.roots) return s;
70	  } catch {
71	    /* fall through */
72	  }
73	  throw new Error("This server's mod state file (/root/.nxeon-mods/state.json) is unreadable — nothing was changed. Contact support.");
74	}
