82	const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");
83	const stamp = (d: Date) => d.toISOString().replace(/[:.]/g, "-");
84	const safeKey = (k: string) => k.replace(/[^A-Za-z0-9._-]/g, "_").slice(0, 120);
