86	/** Which package (other than `exceptKey`) claims `path`. */
87	export function ownerOf(s: GuestState, path: string, exceptKey?: string): PkgState | null {
88	  for (const p of Object.values(s.packages)) {
89	    if (p.key === exceptKey) continue;
90	    if (p.files.some((f) => f.path === path)) return p;
91	  }
92	  return null;
