95	/**
96	 * Delete the game's own synced copy of files we placed (see
97	 * FamilyInstaller.syncedCopy) — only a copy byte-identical to the file we
98	 * recorded, never anything else. Returns how many were removed.
99	 */
100	async function removeSyncedCopies(installer: FamilyInstaller, fs: GuestFs, files: FileRec[]): Promise<number> {
101	  if (!installer.syncedCopy || !installer.syncedRoot) return 0;
102	  let n = 0;
103	  for (const f of files) {
104	    const copy = installer.syncedCopy(f.path);
105	    if (!copy || !isWithin(installer.syncedRoot, copy)) continue;
106	    const st = await fs.stat(copy);
107	    if (!st || st.type !== "file" || st.size !== f.size) continue;
108	    const cur = await fs.readFile(copy, Math.max(f.size + 1, 1024));
109	    if (!cur || sha256(cur) !== f.sha256) continue;
110	    await fs.remove(copy);
111	    n++;
112	  }
113	  return n;
114	}
