116	/**
117	 * modId → the other installed ROOT mods it needs (directly or through a
118	 * dependency chain). The portal's dependency awareness reads this, the
119	 * worker publishes it after every mod job.
120	 */
121	export function dependencyGraph(s: GuestState): Record<string, string[]> {
122	  const rootsOfKey = new Map<string, string[]>();
123	  for (const [id, r] of Object.entries(s.roots)) rootsOfKey.set(r.key, [...(rootsOfKey.get(r.key) ?? []), id]);
124	  const out: Record<string, string[]> = {};
125	  for (const [id, r] of Object.entries(s.roots)) {
126	    const need = new Set<string>();
127	    const seen = new Set<string>([r.key]);
128	    const stack = [...(s.packages[r.key]?.requires ?? [])];
129	    while (stack.length) {
130	      const k = stack.pop()!;
131	      if (seen.has(k)) continue;
132	      seen.add(k);
133	      for (const other of rootsOfKey.get(k) ?? []) if (other !== id) need.add(other);
134	      stack.push(...(s.packages[k]?.requires ?? []));
135	    }
136	    out[id] = [...need].sort();
137	  }
138	  return out;
139	}
