141	export type EngineDeps = {
142	  fs: GuestFs;
143	  fetcher: Fetcher;
144	  mirror?: MirrorLookup | null;
145	  now?: () => Date;
146	  /** Progress callback (job step text + percent). */
147	  progress?: (step: string, pct: number) => void | Promise<void>;
148	};
149	
150	async function download(pkg: ResolvedPackage, deps: EngineDeps): Promise<{ bytes: Buffer; from: "mirror" | "upstream" | "prefetched" }> {
151	  if (pkg.prefetched) return { bytes: pkg.prefetched, from: "prefetched" };
152	  if (deps.mirror) {
153	    const hit = await deps.mirror(pkg.file);
154	    if (hit) return { bytes: hit, from: "mirror" };
155	  }
156	  if (pkg.file.size != null && pkg.file.size > MAX_FILE_BYTES) {
157	    throw new FetchError(`${pkg.name} is ${Math.round(pkg.file.size / 1048576)} MB — over the ${MAX_FILE_BYTES / 1048576} MB one-click limit`, "size");
158	  }
159	  const r = await deps.fetcher(pkg.file.url, {
160	    maxBytes: MAX_FILE_BYTES,
161	    timeoutMs: 180_000,
162	    expect: pkg.file.hashes,
163	    headers: pkg.file.headers,
164	  });
165	  return { bytes: r.bytes, from: "upstream" };
166	}
