168	async function detectOrFail(installer: FamilyInstaller, fs: GuestFs, server: ServerFacts, mod: CatalogFacts | null): Promise<Layout> {
169	  const det = await installer.detect(fs, server, mod);
170	  if ("error" in det) throw new UserFacing(det.error);
171	  return det;
172	}
