174	/** An error whose message is safe and meant for the customer. */
175	export class UserFacing extends Error {}
176	
177	function failure(e: unknown): { ok: false; error: string } {
178	  if (e instanceof UserFacing) return { ok: false, error: e.message };
179	  if (e instanceof FetchError) return { ok: false, error: `Download refused: ${e.message}.` };
180	  const m = e instanceof Error ? e.message : String(e);
181	  return { ok: false, error: m.length > 300 ? m.slice(0, 300) + "…" : m };
182	}
