184	async function pruneBackups(fs: GuestFs) {
185	  const names = (await fs.list(BACKUP_DIR)).filter((n) => /^\d{4}-/.test(n)).sort();
186	  for (const n of names.slice(0, Math.max(0, names.length - KEEP_BACKUPS))) await fs.remove(`${BACKUP_DIR}/${n}`);
187	}
