189	/** Copy `paths` (those that exist) into a fresh backup folder. Returns path→backup copy. */
190	async function backup(fs: GuestFs, label: string, paths: string[], now: Date): Promise<Map<string, string>> {
191	  const out = new Map<string, string>();
192	  if (paths.length === 0) return out;
193	  const dir = `${BACKUP_DIR}/${stamp(now)}-${safeKey(label)}`;
194	  for (const p of paths) {
195	    const st = await fs.stat(p);
196	    if (!st || st.type !== "file") continue;
197	    const dest = `${dir}${p}`;
198	    await fs.copy(p, dest);
199	    out.set(p, dest);
200	  }
201	  if (await fs.stat(STATE_PATH)) await fs.copy(STATE_PATH, `${dir}/state.json`);
202	  await pruneBackups(fs);
203	  return out;
204	}
