206	type Write = { pkg: ResolvedPackage; files: PlacedFile[]; prev: PkgState | null };
207	
208	/**
209	 * Install (or update) a catalogue mod and its required dependencies.
210	 * Idempotent: running it again with nothing new upstream changes nothing.
211	 */
212	export async function installOrUpdate(
213	  installer: FamilyInstaller,
214	  mod: CatalogFacts,
215	  server: ServerFacts,
216	  deps: EngineDeps,
217	  mode: "install" | "update" = "install",
218	): Promise<OpResult> {
219	  const fs = deps.fs;
220	  const now = (deps.now ?? (() => new Date()))();
221	  try {
222	    await deps.progress?.("Checking your server", 5);
223	    const layout = await detectOrFail(installer, fs, server, mod);
224	    const state = await loadState(fs, server.family);
225	    const ctx: InstallerCtx = { server, layout, fetcher: deps.fetcher };
226	
227	    await deps.progress?.(`Resolving ${mod.name} and its dependencies`, 15);
228	    const res = await installer.resolve(mod, ctx);
229	    if ("error" in res) return { ok: false, error: res.error };
230	    const pkgs = res.packages;
231	    const rootPkg = pkgs[pkgs.length - 1];
232	    if (!rootPkg || !rootPkg.root) return { ok: false, error: "Resolver returned no package for this mod." };
233	
234	    // A disabled mod is enabled again, not reinstalled behind the customer's back.
235	    const prevRoot = state.roots[mod.id];
236	    if (prevRoot && state.packages[prevRoot.key]?.disabled && mode === "install") {
237	      return { ok: false, error: `${mod.name} is installed but disabled — enable it instead.` };
238	    }
239	
240	    // ── declared incompatibilities, both directions ─────────────────────────
241	    const incoming = new Set(pkgs.map((p) => p.key));
242	    for (const p of pkgs) {
243	      for (const bad of p.incompatible) {
244	        const have = state.packages[bad.key];
245	        if (have && !have.disabled && !incoming.has(bad.key)) {
246	          return { ok: false, error: `${p.name} is incompatible with ${have.name}, which is installed — remove ${have.name} first.` };
247	        }
248	      }
249	    }
250	    for (const have of Object.values(state.packages)) {
251	      if (have.disabled) continue;
252	      const clash = have.incompatible.find((b) => incoming.has(b.key));
253	      if (clash) return { ok: false, error: `${have.name} (installed) declares it is incompatible with ${clash.name} — nothing was installed.` };
254	    }
255	
256	    // ── download + place, nothing written yet ───────────────────────────────
257	    const writes: Write[] = [];
258	    const notes = [...res.notes];
259	    let total = 0;
260	    let i = 0;
261	    for (const pkg of pkgs) {
262	      i++;
263	      const prev = state.packages[pkg.key] ?? null;
264	      if (prev && prev.version === pkg.version && (await filesIntact(fs, prev))) continue; // already there — idempotent
265	      await deps.progress?.(`Downloading ${pkg.name} ${pkg.version}`, 15 + Math.round((60 * i) / pkgs.length));
266	      const dl = await download(pkg, deps);
267	      total += dl.bytes.length;
268	      if (total > MAX_OP_BYTES) return { ok: false, error: `This install would download more than ${MAX_OP_BYTES / 1048576} MB — too large for one click.` };
269	      const placed = await installer.place(pkg, dl.bytes, ctx);
270	      if ("error" in placed) return { ok: false, error: placed.error };
271	      if (placed.length === 0) return { ok: false, error: `${pkg.name} ${pkg.version} contains nothing this server can load.` };
272	      for (const f of placed) {
273	        if (!isWithin(layout.base, f.path)) return { ok: false, error: `${pkg.name} tried to write outside the game folder — refused.` };
274	      }
275	      if (dl.from === "mirror") notes.push(`${pkg.name} came from the NX Labs mirror (checksum verified).`);
276	      writes.push({ pkg, files: placed, prev });
277	    }
278	
279	    const legacy = (installer.legacyPaths?.(mod, layout) ?? []).filter((p) => isWithin(layout.base, p));
280	
281	    // ── conflicts against files we don't own ───────────────────────────────
282	    const overwrite: string[] = [];
283	    for (const w of writes) {
284	      const prevPaths = new Set(w.prev?.files.map((f) => f.path) ?? []);
285	      for (const f of w.files) {
286	        const other = ownerOf(state, f.path, w.pkg.key);
287	        if (other) {
288	          const rec = other.files.find((x) => x.path === f.path)!;
289	          if (rec.sha256 === sha256(f.data)) continue; // byte-identical shared file — fine
290	          return { ok: false, error: `${w.pkg.name} would overwrite ${f.path}, which belongs to ${other.name} — nothing was changed.` };
291	        }
292	        if (prevPaths.has(f.path) || legacy.includes(f.path)) { overwrite.push(f.path); continue; }
293	        const st = await fs.stat(f.path);
294	        if (!st) continue;
295	        if (st.type === "dir") return { ok: false, error: `${f.path} already exists as a folder — nothing was changed.` };
296	        if (f.overwrite === "backup") { overwrite.push(f.path); continue; }
297	        const cur = await fs.readFile(f.path);
298	        if (cur && sha256(cur) === sha256(f.data)) continue; // same file already there (installed by hand) — adopt it
299	        return {
300	          ok: false,
301	          error: `${f.path} already exists and wasn't installed by Nxeon (added by hand?). Remove or rename it in Files, then try again — nothing was changed.`,
302	        };
303	      }
304	    }
305	
306	    // Files of the previous version that the new version no longer ships.
307	    const stale: string[] = [];
308	    for (const w of writes) {
309	      if (!w.prev) continue;
310	      const keep = new Set(w.files.map((f) => f.path));
311	      for (const f of w.prev.files) if (!keep.has(f.path) && !ownerOf(state, f.path, w.pkg.key)) stale.push(f.path);
312	    }
313	
314	    // Nothing to do at all → idempotent success, no restart needed.
315	    const existingLegacy: string[] = [];
316	    for (const p of legacy) {
317	      // A "legacy" path the engine itself now owns (same filename) is not legacy.
318	      if (ownerOf(state, p) || writes.some((w) => w.files.some((f) => f.path === p))) continue;
319	      if (await fs.stat(p)) existingLegacy.push(p);
320	    }
321	    if (writes.length === 0 && existingLegacy.length === 0) {
322	      addRoots(state, pkgs, mod);
323	      await saveState(fs, state);
324	      return { ok: true, version: rootPkg.version, versionId: rootPkg.versionId ?? null, fileName: rootFileName(state, rootPkg.key), restartRequired: false, changed: [], notes: [...notes, `${mod.name} ${rootPkg.version} is already installed and up to date.`] };
325	    }
326	
327	    // ── backup, then staged write ───────────────────────────────────────────
328	    await deps.progress?.("Backing up files that will change", 80);
329	    // Config the installer asked to keep a copy of (Cyrus: the plugin's own folder), backup only.
330	    const keep: string[] = [];
331	    for (const d of res.alsoBackupDirs ?? []) {
332	      if (!isWithin(layout.base, d)) continue;
333	      for (const f of (await fs.list(d)).slice(0, 40)) {
334	        const st = await fs.stat(`${d}/${f}`);
335	        if (st?.type === "file" && st.size <= 4 * 1024 * 1024) keep.push(`${d}/${f}`);
336	      }
337	    }
338	    const backups = await backup(fs, mod.slug, [...overwrite, ...stale, ...existingLegacy, ...keep], now);
339	
340	    await deps.progress?.("Writing files to your server", 88);
341	    const written: string[] = [];
342	    const created: string[] = [];
343	    try {
344	      for (const w of writes) {
345	        for (const f of w.files) {
346	          const existed = !!(await fs.stat(f.path));
347	          const part = `${f.path}.nxeon-part`;
348	          await fs.writeFile(part, f.data);
349	          await fs.rename(part, f.path);
350	          written.push(f.path);
351	          if (!existed) created.push(f.path);
352	        }
353	      }
354	      for (const p of stale) await fs.remove(p);
355	      for (const w of writes) {
356	        if (!w.prev) continue;
357	        const keep = new Set(w.files.map((f) => f.path));
358	        await removeSyncedCopies(installer, fs, w.prev.files.filter((f) => stale.includes(f.path) && !keep.has(f.path)));
359	      }
360	      for (const p of existingLegacy) if (!written.includes(p)) await fs.remove(p);
361	
362	      // State: record exactly what we wrote.
363	      for (const w of writes) {
364	        const prev = w.prev;
365	        state.packages[w.pkg.key] = {
366	          key: w.pkg.key,
367	          name: w.pkg.name,
368	          version: w.pkg.version,
369	          versionId: w.pkg.versionId ?? null,
370	          files: w.files.map((f) => ({ path: f.path, sha256: sha256(f.data), size: f.data.length })),
371	          roots: prev?.roots ?? [],
372	          requires: w.pkg.requires,
373	          incompatible: w.pkg.incompatible,
374	          disabled: false,
375	          installedAt: prev?.installedAt ?? now.toISOString(),
376	          updatedAt: now.toISOString(),
377	        };
378	      }
379	      addRoots(state, pkgs, mod);
380	
381	      if (installer.configure) {
382	        const edits = await installer.configure(fs, layout, enabledList(state), allList(state));
383	        for (const e of edits) {
384	          if (!isWithin(layout.base, e.path)) continue;
385	          if (!backups.has(e.path) && (await fs.stat(e.path))) await backup(fs, `${mod.slug}-config`, [e.path], now);
386	          await fs.writeFile(`${e.path}.nxeon-part`, e.data);
387	          await fs.rename(`${e.path}.nxeon-part`, e.path);
388	        }
389	      }
390	      await saveState(fs, state);
391	    } catch (e) {
392	      // Roll back: new files out, overwritten files back from the backup.
393	      for (const p of created) await fs.remove(p).catch(() => {});
394	      for (const [orig, copy] of backups) await fs.copy(copy, orig).catch(() => {});
395	      for (const w of writes) for (const f of w.files) await fs.remove(`${f.path}.nxeon-part`).catch(() => {});
396	      const why = failure(e).error;
397	      return { ok: false, error: `Writing to your server failed and the change was rolled back: ${why}` };
398	    }
399	    await fs.chownLike(layout.base, [...new Set(written.map((p) => p.split("/").slice(0, -1).join("/")))].filter((d) => isWithin(layout.base, d)));
400	
401	    const changed = writes.map((w) =>
402	      w.prev ? `updated ${w.pkg.name} ${w.prev.version} → ${w.pkg.version}` : `${w.pkg.root ? "installed" : "added dependency"} ${w.pkg.name} ${w.pkg.version}`,
403	    );
404	    if (existingLegacy.length) changed.push(`replaced ${existingLegacy.length} file(s) from the older Nxeon installer`);
405	    return { ok: true, version: rootPkg.version, versionId: rootPkg.versionId ?? null, fileName: rootFileName(state, rootPkg.key), restartRequired: installer.restartRequired, changed, notes };
406	  } catch (e) {
407	    return failure(e);
408	  }
409	}
