411	/** Basename of the first file a package placed (what the mod-health check and the panel call its file). */
412	function rootFileName(state: GuestState, key: string): string | null {
413	  return state.packages[key]?.files[0]?.path.split("/").pop() ?? null;
414	}
415	
416	async function filesIntact(fs: GuestFs, p: PkgState): Promise<boolean> {
417	  if (p.disabled) return true;
418	  for (const f of p.files) {
419	    const st = await fs.stat(f.path);
420	    if (!st || st.type !== "file" || st.size !== f.size) return false;
421	  }
422	  return p.files.length > 0;
423	}
