425	function addRoots(state: GuestState, pkgs: ResolvedPackage[], mod: CatalogFacts) {
426	  const root = pkgs[pkgs.length - 1];
427	  state.roots[mod.id] = { key: root.key, name: mod.name };
428	  for (const p of pkgs) {
429	    const st = state.packages[p.key];
430	    if (st && !st.roots.includes(mod.id)) st.roots.push(mod.id);
431	  }
432	}
