434	function enabledList(s: GuestState) {
435	  return Object.values(s.packages).filter((p) => !p.disabled).map((p) => ({ key: p.key, name: p.name, version: p.version }));
436	}
437	function allList(s: GuestState) {
438	  return Object.values(s.packages).map((p) => ({ key: p.key, name: p.name }));
439	}
