441	/** Remove a catalogue mod; dependencies go only when nothing else needs them. */
442	export async function uninstall(installer: FamilyInstaller, mod: CatalogFacts, server: ServerFacts, deps: EngineDeps): Promise<OpResult> {
443	  const fs = deps.fs;
444	  try {
445	    await deps.progress?.("Checking your server", 10);
446	    const layout = await detectOrFail(installer, fs, server, mod);
447	    const state = await loadState(fs, server.family);
448	    const legacy = (installer.legacyPaths?.(mod, layout) ?? []).filter((p) => isWithin(layout.base, p));
449	    const removed: string[] = [];
450	    const dropLegacy = async () => {
451	      for (const p of legacy) {
452	        if (ownerOf(state, p)) continue; // the engine owns it now — handled with the package
453	        if (await fs.stat(p)) {
454	          await fs.remove(p);
455	          removed.push(p);
456	        }
457	      }
458	    };
459	    if (!state.roots[mod.id]) {
460	      await dropLegacy();
461	      return {
462	        ok: true,
463	        restartRequired: removed.length > 0 && installer.restartRequired,
464	        changed: removed.length ? [`removed ${mod.name}`] : [],
465	        notes: removed.length ? [] : [`${mod.name} wasn't on the server (nothing to remove).`],
466	      };
467	    }
468	
469	    // Is this mod's package something ANOTHER installed mod needs?
470	    const rootKey = state.roots[mod.id].key;
471	    const blockers = Object.entries(state.roots)
472	      .filter(([id, r]) => id !== mod.id && r.key !== rootKey && state.packages[r.key]?.requires.includes(rootKey))
473	      .map(([, r]) => r.name);
474	    if (blockers.length) return { ok: false, error: `${blockers.join(", ")} need${blockers.length === 1 ? "s" : ""} ${mod.name} — remove ${blockers.length === 1 ? "it" : "them"} first.` };
475	
476	    await deps.progress?.(`Removing ${mod.name}`, 50);
477	    await dropLegacy();
478	    delete state.roots[mod.id];
479	    const gone: string[] = [];
480	    for (const p of Object.values(state.packages)) {
481	      p.roots = p.roots.filter((r) => r !== mod.id);
482	      // A package another mod still installed as its own root stays.
483	      const stillRoot = Object.values(state.roots).some((r) => r.key === p.key);
484	      if (p.roots.length === 0 && !stillRoot) gone.push(p.key);
485	    }
486	    for (const key of gone) {
487	      const p = state.packages[key];
488	      delete state.packages[key];
489	      for (const f of p.files) {
490	        if (ownerOf(state, f.path)) continue; // shared identical file still needed
491	        const at = p.disabled ? disabledPath(p.key, f.path) : f.path;
492	        await fs.remove(at);
493	      }
494	      if (p.disabled) await fs.remove(`${DISABLED_DIR}/${safeKey(p.key)}`);
495	      await removeSyncedCopies(installer, fs, p.files.filter((f) => !ownerOf(state, f.path)));
496	      await removeEmptyParents(fs, p.files.map((f) => f.path), layout);
497	      removed.push(p.name);
498	    }
499	    if (installer.configure) {
500	      for (const e of await installer.configure(fs, layout, enabledList(state), allList(state))) {
501	        if (!isWithin(layout.base, e.path)) continue;
502	        await fs.writeFile(`${e.path}.nxeon-part`, e.data);
503	        await fs.rename(`${e.path}.nxeon-part`, e.path);
504	      }
505	    }
506	    await saveState(fs, state);
507	    const extra = gone.length - 1;
508	    return {
509	      ok: true,
510	      restartRequired: installer.restartRequired,
511	      changed: [`removed ${mod.name}`, ...(extra > 0 ? [`also removed ${extra} dependenc${extra === 1 ? "y" : "ies"} nothing else needed`] : [])],
512	      notes: [],
513	    };
514	  } catch (e) {
