/**
 * Per-family one-click mod coverage — the single table the worker, the portal
 * and docs/MODS-COVERAGE.md agree on.
 *
 *  engine      — lib/mods/engine.ts + an installer in this folder (resolve →
 *                verified download → safe placement → state/rollback). Supports
 *                install, update, enable/disable, uninstall.
 *  legacy      — a family-specific path in worker/game-mods.ts that predates
 *                the engine and was verified on a live server (Steam Workshop
 *                config-writes, TShock restart-and-verify, Vintage Story,
 *                Satisfactory, Arma Reforger). Install + uninstall; the
 *                game itself owns updates for Workshop families.
 *  unavailable — no honest one-click path yet; `reason` says why, in words a
 *                customer can act on. The panel shows the catalogue with
 *                manual-install guidance, never an Install button.
 */
import type { FamilyInstaller } from "../types";
import { minecraftInstaller } from "./minecraft";
