1	/**
2	 * Cyrus mod lifecycle: the DB-backed half (server-only; no next/* imports, so the worker and
3	 * the portal both use it). The pure rules live next door (state/compat/install-plan/creator).
4	 *
5	 * What it answers:
6	 *   - lifecycleForServer(serverId): every Cyrus mod on a server with its lifecycle state
7	 *     (Enabled / Disabled / Pending restart / Failed / Broken / Outdated + why);
8	 *   - summariesForServers(ids): the counts the server card and banner show;
9	 *   - installPlansFor(build, actor): the install plan for each of the actor's servers;
10	 *   - publicInstallAllowed(): may someone install another creator's PUBLISHED version.
11	 */
12	import type { CyrusCreatorAlert, ModBuild } from "@prisma/client";
13	import { cyrusDb as db } from "../db";
14	import { CYRUS_SOURCE, CYRUS_VARIANTS } from "../source";
15	import { currentVersion as chainHead, displayName, succeededVersions, versionLabel } from "../mods/doc";
16	import { getHost, type HostInstallRow, type HostServerRow } from "../host";
17	import { outdatedReasons, checkCompat } from "./compat";
18	import { deriveLifecycle, type LifecycleView } from "./state";
19	import { buildInstallPlan, type InstallPlan, type PlanServer } from "./install-plan";
20	import { supportFor } from "./support";
21	import { updateWithCyrusHref } from "./creator";
