23	type HealthPlan = { startedAt?: string; gameVersion?: string | null; cyrus?: { modId: string; buildId: string | null; status: string; apiMismatch: boolean; evidence: string[] }[] };
24	
25	const safetyOf = (b: Pick<ModBuild, "result">): "pass" | "warn" | "block" | null => {
26	  const v = (b.result as { safety?: { verdict?: string } } | null)?.safety?.verdict;
27	  return v === "pass" || v === "warn" || v === "block" ? v : null;
28	};
