30	/** The game version a server runs: its pinned config, else what the last log read reported. */
31	export async function serverGameVersion(server: Pick<HostServerRow, "id" | "gameConfig">): Promise<string | null> {
32	  const pinned = getHost().servers.pinnedVersion(server.gameConfig);
33	  if (pinned) return pinned;
34	  const run = await getHost().servers.lastHealthRun(server.id).catch(() => null);
35	  return ((run?.plan ?? null) as HealthPlan | null)?.gameVersion ?? null;
36	}
