38	async function chainsFor(roots: string[]): Promise<Map<string, ModBuild[]>> {
39	  const out = new Map<string, ModBuild[]>();
40	  if (!roots.length) return out;
41	  const rows = await db.modBuild.findMany({ where: { OR: [{ id: { in: roots } }, { rootBuildId: { in: roots } }] }, orderBy: { createdAt: "asc" } });
42	  for (const b of rows) {
43	    const r = b.rootBuildId ?? b.id;
44	    out.set(r, [...(out.get(r) ?? []), b]);
45	  }
46	  return out;
47	}
