49	export type CyrusLifecycleRow = {
50	  modId: string;
51	  rootBuildId: string;
52	  name: string;
53	  view: LifecycleView;
54	  installedLabel: string | null;
55	  latestLabel: string | null;
56	  latestBuildId: string | null;
57	  updateAvailable: boolean;
58	  autoUpdate: boolean;
59	  serverVersion: string | null;
60	};
