75	export async function lifecycleForServer(serverId: string): Promise<CyrusLifecycleRow[]> {
76	  const server = await getHost().servers.get(serverId);
77	  if (!server) return [];
78	  const rows = await getHost().records.onServer(serverId, CYRUS_SOURCE);
79	  if (!rows.length) return [];
80	  return lifecycleRows(server, rows);
81	}
