144	export type ServerCyrusSummary = { broken: number; outdated: number; failed: number; pendingRestart: number; autoDisabled: number; total: number; worst: "bad" | "warn" | "info" | null; headline: string | null };
145	
146	export function summarize(rows: CyrusLifecycleRow[]): ServerCyrusSummary {
147	  const n = (s: string) => rows.filter((r) => r.view.state === s).length;
148	  const autoDisabled = rows.filter((r) => r.view.state === "disabled" && r.view.notes[0]?.startsWith("We switched it off")).length;
149	  const s = { broken: n("broken"), outdated: n("outdated"), failed: n("failed"), pendingRestart: n("pending_restart"), autoDisabled, total: rows.length };
150	  const worst = s.broken || s.failed || s.autoDisabled ? "bad" : s.outdated ? "warn" : s.pendingRestart ? "info" : null;
151	  const first = (st: string) => rows.find((r) => r.view.state === st)?.name;
152	  const headline =
153	    s.broken ? `${first("broken")}${s.broken > 1 ? ` and ${s.broken - 1} more` : ""} ${s.broken > 1 ? "are" : "is"} reporting errors`
154	    : s.autoDisabled ? `We switched off ${s.autoDisabled === 1 ? "a Cyrus mod" : `${s.autoDisabled} Cyrus mods`} after the game kept crashing`
155	    : s.failed ? `A change to ${first("failed")} failed`
156	    : s.outdated ? `${s.outdated === 1 ? `${first("outdated")} is` : `${s.outdated} Cyrus mods are`} out of date`
157	    : s.pendingRestart ? "Restart to load your Cyrus mod changes"
158	    : null;
159	  return { ...s, worst, headline };
160	}
