162	/** Per-server summaries for a list of servers (server cards). Servers without Cyrus mods are left out. */
163	export async function summariesForServers(serverIds: string[]): Promise<Map<string, ServerCyrusSummary>> {
164	  const out = new Map<string, ServerCyrusSummary>();
165	  if (!serverIds.length) return out;
166	  const withCyrus = await getHost().records.serversWithSource(serverIds, CYRUS_SOURCE);
167	  for (const serverId of withCyrus.slice(0, 40)) {
168	    const rows = await lifecycleForServer(serverId).catch(() => []);
169	    if (rows.length) out.set(serverId, summarize(rows));
170	  }
171	  return out;
172	}
