176	/**
177	 * May `actorId` install this build of someone else's mod? Only PUBLISHED, visible,
178	 * scanned-not-blocked versions, and only while Setting cyrus_install_published_enabled is on
179	 * (default OFF: the 2026-10-07 owner decision was "not offered"; the code is ready, the owner
180	 * decides). The creator's own builds are always allowed.
181	 */
182	export async function publicInstallAllowed(build: ModBuild, actorId: string): Promise<boolean> {
183	  if (build.userId === actorId) return true;
184	  if (!(await getHost().settings.getBool("cyrus_install_published_enabled", false))) return false;
185	  if (build.status !== "succeeded" || !build.jarPath || safetyOf(build) === "block") return false;
186	  const page = await db.cyrusModPage.findUnique({ where: { rootBuildId: build.rootBuildId ?? build.id } });
187	  if (!page || page.visibility !== "PUBLIC" || page.hiddenAt) return false;
188	  // Same flag as lib/cyrus-mods/gate.ts (not imported: that module pulls in next/* + auth, and the worker uses this file).
189	  return getHost().settings.getBool("cyrus_mods_public_enabled", false).catch(() => false);
190	}
