192	/** Config Studio: saved settings revisions this server has not been sent yet (set by lib/modbuilder/config-delivery.ts installPlansWithConfig, only while CYRUS_DELIVERY + CYRUS_CONFIG_STUDIO are on). */
193	export type PendingConfig = { root: string; revisionId: string; seq: number; message: string | null; applies: "live" | "reload" | "restart" | "none"; revisions: number };
194	export type ServerPlan = { server: { id: string; name: string; status: string; variant: string | null; version: string | null }; plan: InstallPlan; pendingConfig?: PendingConfig };
195	
196	/** One install plan per server the actor owns that runs the mod's game. */
197	export async function installPlansFor(build: ModBuild, actorId: string): Promise<{ game: string; plans: ServerPlan[] }> {
198	  const gameId = "minecraft"; // ModBuild is Minecraft-only today; other games join through GameSupport.
199	  const support = supportFor(gameId)!;
200	  const root = build.rootBuildId ?? build.id;
201	  const chain = (await chainsFor([root])).get(root) ?? [];
202	  const builtFor = [...new Set(succeededVersions(chain).map((b) => b.mcVersion))];
203	  const servers = await getHost().servers.listForUser(actorId);
204	  const gmId = await getHost().records.catalogId(CYRUS_SOURCE, root);
205	  const existing = gmId ? await getHost().records.ofMod(gmId, servers.map((s) => s.id)) : [];
206	  const plans: ServerPlan[] = [];
207	  for (const s of servers) {
208	    if (getHost().servers.familyOf(s) !== "minecraft") continue;
209	    const variant = (s.gameVariant || "vanilla").toLowerCase();
210	    const version = await serverGameVersion(s);
211	    const ex = existing.find((e) => e.serverId === s.id);
212	    const ps: PlanServer = {
213	      id: s.id,
214	      name: s.label || s.hostname,
215	      sameGame: true,
216	      variantOk: CYRUS_VARIANTS.includes(variant),
217	      variantNote: `Runs ${variant[0].toUpperCase() + variant.slice(1)}; Cyrus plugins need Paper or Purpur (switch it in the server's Settings).`,
218	      running: s.status === "RUNNING",
219	      version,
220	      existing: ex && ex.status !== "REMOVED" ? { status: ex.status, buildId: ex.versionId } : null,
221	    };
222	    const plan = buildInstallPlan(support, { name: chain.length ? displayName(chain) : (build.pluginName ?? "This mod"), buildId: build.id, target: build.mcVersion, builtFor, installable: true, safety: safetyOf(build) }, ps);
223	    plans.push({ server: { id: s.id, name: ps.name, status: s.status, variant, version }, plan });
224	  }
225	  return { game: support.name, plans };
226	}
