233	export async function toAlertViews(rows: CyrusCreatorAlert[]): Promise<CreatorAlertView[]> {
234	  const roots = [...new Set(rows.map((r) => r.rootBuildId))];
235	  const [pages, chains] = await Promise.all([
236	    db.cyrusModPage.findMany({ where: { rootBuildId: { in: roots } }, select: { rootBuildId: true, slug: true, title: true } }),
237	    chainsFor(roots),
238	  ]);
239	  return rows.map((r) => {
240	    const p = pages.find((x) => x.rootBuildId === r.rootBuildId);
241	    const chain = chains.get(r.rootBuildId) ?? [];
242	    // The refine path continues from the mod's CURRENT version (the creator's restored head, else the newest).
243	    const head = chainHead(chain)?.id ?? r.rootBuildId;
244	    return {
245	      id: r.id, kind: r.kind, title: r.title, body: r.body, servers: r.servers, targetVersion: r.targetVersion, buildable: r.buildable,
246	      modTitle: p?.title ?? (chain.length ? displayName(chain) : "Your Cyrus mod"),
247	      pageSlug: p?.slug ?? null,
248	      updateHref: r.buildable || r.kind === "ERROR_REPORTS" ? updateWithCyrusHref(head, r.buildable ? r.targetVersion : null) : null,
249	      firstSeenAt: r.firstSeenAt.toISOString(), lastSeenAt: r.lastSeenAt.toISOString(),
250	    };
251	  });
252	}
