1	/**
2	 * The install plan a customer confirms before a Cyrus mod goes onto their server (PURE).
3	 * Everything comes from the game's GameSupport (path, packaging, restart, hot reload, which
4	 * side needs the files) plus the version check (./compat.ts). The SAME function runs in the
5	 * dialog and again on the server when the install is submitted, so a warning the customer
6	 * didn't tick can't be skipped by calling the API directly.
7	 */
8	import type { GameSupport } from "../games/support";
9	import { checkCompat, type CompatReason } from "./compat";
10	import { cyrusConfig } from "../config";
11	
12	export type PlanServer = {
13	  id: string;
14	  name: string;
15	  /** Server game family matches the mod's game. */
16	  sameGame: boolean;
17	  /** Runs a loader/variant Cyrus mods can go on (Paper/Purpur for Minecraft). */
18	  variantOk: boolean;
19	  variantNote?: string;
20	  running: boolean;
21	  version: string | null;
22	  /** The mod's state on this server already (ServerMod.status), null = not installed. */
23	  existing: { status: string; buildId: string | null } | null;
24	};
25	
26	export type PlanMod = {
27	  name: string;
28	  /** The build being installed. */
29	  buildId: string;
30	  /** Its target game version (ModBuild.mcVersion). */
31	  target: string;
32	  builtFor: string[];
33	  /** A real installer exists for this game's Cyrus mods (Minecraft today). */
34	  installable: boolean;
35	  safety: "pass" | "warn" | "block" | null;
36	};
37	
38	export type InstallStep = { id: string; text: string };
39	
40	export type InstallPlan = {
41	  serverId: string;
42	  /** install | update (same mod, other version) | none (already this version) */
43	  op: "install" | "update" | "none";
44	  /** Hard stops: install is refused while any is present. */
45	  blockers: string[];
46	  /** Need an explicit tick; `id` is what the confirm sends back. */
47	  warnings: { id: string; text: string }[];
48	  steps: InstallStep[];
49	  /** Players must install something on their own PC (side client/both). */
50	  players: { needed: boolean; text: string | null };
51	  restart: "required" | "hot" | "none";
52	  backupNote: string;
53	  rollbackNote: string;
54	};
55	
56	export function buildInstallPlan(support: GameSupport, mod: PlanMod, s: PlanServer): InstallPlan {
57	  const blockers: string[] = [];
58	  const warnings: { id: string; text: string }[] = [];
59	  const g = support.name;
60	  if (!mod.installable) blockers.push(`One-click installs of Cyrus ${g} mods aren't available yet. Download the files and follow the steps on the mod page.`);
61	  if (!s.sameGame) blockers.push(`${s.name} isn't a ${g} server.`);
62	  else if (!s.variantOk) blockers.push(s.variantNote ?? `${s.name} runs a server type this mod can't load on.`);
63	  if (s.sameGame && !s.running) blockers.push("Start the server first: mods are installed onto the running server.");
64	  if (mod.safety === "block") blockers.push("This version failed the safety scan, so it can't be installed.");
65	  if (s.existing && !["INSTALLED", "FAILED", "REMOVED"].includes(s.existing.status)) {
66	    blockers.push(s.existing.status === "DISABLED" ? `${mod.name} is switched off on ${s.name}. Switch it on in the Mods tab first.` : `${mod.name} is busy on ${s.name} right now. Try again in a moment.`);
67	  }
68	
69	  const compat = s.sameGame ? checkCompat({ support, serverVersion: s.version, target: mod.target, builtFor: mod.builtFor }) : null;
70	  for (const r of compat?.reasons ?? []) (r.level === "block" ? blockers.push(r.text) : warnings.push({ id: r.code, text: r.text }));
71	  if (mod.safety === "warn") warnings.push({ id: "safety-warn", text: "The safety scan left notes on this version (see the mod's Code tab). It was not blocked." });
72	
73	  const side = support.install.side;
74	  const players = side === "server"
75	    ? { needed: false, text: null }
76	    : { needed: true, text: support.install.clientNote ?? `Players must also install ${mod.name} on their own PC, the same version as the server, or they won't be able to join.` };
77	  if (players.needed) warnings.push({ id: "players-must-install", text: `Players must also install this. ${players.text}` });
78	
79	  const op: InstallPlan["op"] = s.existing?.status === "INSTALLED" ? (s.existing.buildId === mod.buildId ? "none" : "update") : "install";
80	  const restart: InstallPlan["restart"] = support.install.hotReload ? "hot" : support.install.needsRestart ? "required" : "none";
81	  const where = support.install.serverPath;
82	  const steps: InstallStep[] = [
83	    { id: "check", text: `Check ${s.name}: game version, ${support.loader.name}, free space.` },
84	    { id: "backup", text: op === "update" ? `Back up the current ${mod.name} file and its config.` : `Back up anything we would replace in ${where}.` },
85	    { id: "place", text: `Place ${mod.name} (${support.install.packaging}) in ${where}. Its existing config and data stay.` },
86	    restart === "hot"
87	      ? { id: "load", text: `${support.loader.name} loads it on its own, no restart.` }
88	      : { id: "load", text: "Restart the server to load it (we'll offer a restart when it's in place)." },
