1	/**
2	 * The lifecycle state of a Cyrus mod on one server (PURE, client-safe).
3	 *
4	 * The DB row (ServerMod.status) says what the ENGINE did; this adds what the customer needs to
5	 * know on top: does it need a restart, did it break, is it out of date. One function derives the
6	 * state everyone shows (Mods tab row, server card, server banner, NxLabs "On my servers"), and
7	 * one transition table documents and tests how it moves (docs/DOCUMENTATION.md has the diagram).
8	 *
9	 *   resting:   enabled · disabled · pending_restart · failed · broken · outdated
10	 *   in flight: installing · updating · enabling · disabling · removing
11	 *
12	 * Priority when several are true: in flight > failed > broken > disabled > pending_restart >
13	 * outdated > enabled. ("Broken" outranks "Disabled" only while it is still switched on: a mod we
14	 * auto-disabled is Disabled, with the reason.)
15	 */
16	import type { OutdatedReason } from "./compat";
17	
18	export type LifecycleState =
19	  | "installing" | "updating" | "enabling" | "disabling" | "removing"
20	  | "enabled" | "disabled" | "pending_restart" | "failed" | "broken" | "outdated";
21	
22	export type LifecycleAction = "enable" | "disable" | "update" | "rollback" | "restart" | "remove" | "retry" | "rebuild";
23	
24	export type LifecycleInput = {
25	  /** ServerMod.status */
26	  status: string;
27	  /** ServerMod.error (the last failure). */
28	  error: string | null;
29	  /** The last mod job changed this mod and the game hasn't restarted since. */
30	  restartPending: boolean;
31	  /** Open BROKEN signal / a load verdict "error" for the installed build. */
32	  broken: { evidence: string | null; apiMismatch: boolean } | null;
33	  /** We switched it off ourselves (crash loop after install). */
34	  autoDisabled: { why: string } | null;
35	  outdated: OutdatedReason[];
36	  /** The previous version is still on the server after a failed update (engine rolled back). */
37	  rolledBack: boolean;
38	};
39	
40	export type LifecycleView = {
41	  state: LifecycleState;
42	  label: string;
43	  tone: "ok" | "info" | "warn" | "bad" | "muted";
44	  /** Customer-facing sentences, most important first. */
45	  notes: string[];
46	  actions: LifecycleAction[];
47	};
48	
49	const FLIGHT: Record<string, LifecycleState> = { INSTALLING: "installing", UPDATING: "updating", ENABLING: "enabling", DISABLING: "disabling", REMOVING: "removing" };
50	
51	export const STATE_LABEL: Record<LifecycleState, string> = {
52	  installing: "Installing", updating: "Updating", enabling: "Enabling", disabling: "Disabling", removing: "Removing",
53	  enabled: "Enabled", disabled: "Disabled", pending_restart: "Pending restart", failed: "Failed", broken: "Broken", outdated: "Outdated",
54	};
55	
56	export function deriveLifecycle(i: LifecycleInput): LifecycleView {
57	  const flight = FLIGHT[i.status];
58	  if (flight) return { state: flight, label: STATE_LABEL[flight], tone: "info", notes: [], actions: [] };
59	
60	  if (i.status === "FAILED") {
61	    return {
62	      state: "failed", label: "Failed", tone: "bad",
63	      notes: [i.error ?? "The last change didn't go through.", "Nothing half-installed was left behind: the engine rolls back a write that fails."],
64	      actions: ["retry", "remove"],
65	    };
66	  }
67	
68	  const on = i.status === "INSTALLED";
69	  const notes: string[] = [];
70	  if (i.rolledBack && i.error) notes.push(`The update failed and the previous version was kept: ${i.error}`);
71	
72	  if (on && i.broken) {
73	    return {
74	      state: "broken", label: "Broken", tone: "bad",
75	      notes: [
76	        i.broken.apiMismatch
77	          ? "The game log shows this mod calling something your game version doesn't have: it's out of date for this version."
78	          : "The game log shows errors naming this mod.",
79	        ...(i.broken.evidence ? [i.broken.evidence] : []),
80	        ...notes,
81	      ],
82	      actions: ["update", "rollback", "disable", "rebuild"],
83	    };
84	  }
85	
86	  if (i.status === "DISABLED") {
87	    if (i.autoDisabled) notes.unshift(`We switched it off: ${i.autoDisabled.why} Its config and data were kept.`);
88	    return { state: "disabled", label: "Disabled", tone: "muted", notes, actions: ["enable", "remove"] };
89	  }
90	
91	  if (on && i.restartPending) {
92	    return { state: "pending_restart", label: "Pending restart", tone: "info", notes: ["Restart the server to load this change.", ...notes], actions: ["restart", "disable"] };
93	  }
94	
95	  if (on && i.outdated.length) {
96	    return {
97	      state: "outdated", label: "Outdated", tone: "warn",
98	      notes: [...i.outdated.map((o) => o.text), ...notes],
99	      actions: i.outdated.some((o) => o.code === "newer-build") ? ["update", "disable"] : ["rebuild", "disable"],
100	    };
101	  }
102	
103	  return { state: "enabled", label: "Enabled", tone: "ok", notes, actions: ["disable", "remove"] };
104	}
105	
106	/* ── transition table (documentation + tests; the engine/worker do the moving) ── */
107	
108	export type LifecycleEvent =
109	  | "install" | "update" | "enable" | "disable" | "remove"
110	  | "job_ok_restart" | "job_ok_hot" | "job_failed" | "update_failed_rolled_back"
111	  | "restarted" | "log_error" | "crash_loop" | "log_clean" | "game_ahead" | "newer_build";
112	
113	export const TRANSITIONS: Record<LifecycleState, Partial<Record<LifecycleEvent, LifecycleState>>> = {
114	  installing: { job_ok_restart: "pending_restart", job_ok_hot: "enabled", job_failed: "failed" },
115	  updating: { job_ok_restart: "pending_restart", job_ok_hot: "enabled", job_failed: "failed", update_failed_rolled_back: "enabled" },
116	  enabling: { job_ok_restart: "pending_restart", job_ok_hot: "enabled", job_failed: "failed" },
117	  disabling: { job_ok_restart: "disabled", job_ok_hot: "disabled", job_failed: "enabled" },
118	  removing: { job_failed: "enabled" },
119	  enabled: { disable: "disabling", update: "updating", remove: "removing", log_error: "broken", crash_loop: "disabling", game_ahead: "outdated", newer_build: "outdated" },
120	  pending_restart: { restarted: "enabled", log_error: "broken", crash_loop: "disabling", disable: "disabling" },
121	  outdated: { update: "updating", disable: "disabling", remove: "removing", log_error: "broken", crash_loop: "disabling" },
122	  broken: { update: "updating", disable: "disabling", remove: "removing", log_clean: "enabled", crash_loop: "disabling" },
123	  disabled: { enable: "enabling", remove: "removing" },
124	  failed: { install: "installing", remove: "removing" },
125	};
126	
127	/** Next state for an event, or null when the event can't happen in that state. */
128	export function nextState(s: LifecycleState, e: LifecycleEvent): LifecycleState | null {
129	  return TRANSITIONS[s][e] ?? null;
130	}
