/**
 * Batch mod changes (the Installed list's "apply N changes"): pure helpers
 * shared by lib/mods/queue.ts (enqueue) and worker/game-mods.ts (apply).
 *
 * A batch is ONE GAME_MOD_SYNC job whose payload carries `ops`, the order the
 * portal worked out with lib/mods/toggle-policy.ts planToggles() — disables of
 * dependents before the mods they need, enables of needed mods first. The
 * worker applies pending rows in that order; rows the payload doesn't name
 * (none, normally) keep their old updatedAt order after them.
 */
import type { ModOp } from "./queue";

export type BatchOp = { modId: string; op: ModOp };

export const MAX_BATCH = 25;

export function batchOpsFromPayload(payload: unknown): BatchOp[] {
  const p = (payload && typeof payload === "object" ? payload : {}) as { ops?: unknown; modId?: unknown; op?: unknown };
  const out: BatchOp[] = [];
  if (Array.isArray(p.ops)) {
    for (const o of p.ops.slice(0, MAX_BATCH)) {
      const r = (o ?? {}) as { modId?: unknown; op?: unknown };
      if (typeof r.modId === "string" && typeof r.op === "string") out.push({ modId: r.modId, op: r.op as ModOp });
    }
  } else if (typeof p.modId === "string" && typeof p.op === "string") {
    out.push({ modId: p.modId, op: p.op as ModOp });
  }
  return out;
}

/** Stable re-order of pending rows to follow the job's planned op order. */
export function orderPendingByPlan<T extends { modId: string }>(rows: T[], payload: unknown): T[] {
  const ops = batchOpsFromPayload(payload);
  if (ops.length < 2) return rows;
  const rank = new Map(ops.map((o, i) => [o.modId, i]));
  return rows
    .map((r, i) => ({ r, i }))
    .sort((a, b) => (rank.get(a.r.modId) ?? ops.length + a.i) - (rank.get(b.r.modId) ?? ops.length + b.i))
    .map((x) => x.r);
}
/**
 * Cyrus R5 delivery job (worker side): Nxeon's implementation of the orchestrator's host seam
 * (lib/cyrus/delivery/types.ts DeliveryHost) and the job entry point.
 *
 * Wiring (the only one, and only as far as is clearly safe): a GAME_MOD_SYNC job whose payload carries
 * `{ cyrusDelivery: { v: 1, op, buildId?, projectId?, serverModId?, prev?, restartPolicy, key, acknowledge?, ... } }`
 * (schema: lib/cyrus/delivery/request.ts; op "config" = a Config Studio values-only send, handled by deliverConfig)
 * (a payload DISCRIMINATOR on an existing job type: no new enum value, no new table) is handed to
 * `cyrusDeliveryJob` instead of the normal mod reconcile. The portal enqueues it through lib/modbuilder/delivery.ts
 * (route app/api/cyrus/delivery/v1, wiring phase 2); the job body itself is host-neutral (lib/cyrus/delivery/job.ts) and
 * refuses unless CYRUS_DELIVERY=1 in the worker. Each part is still behind its own flag (CYRUS_MANAGED_PLUGINS_REAL,
 * CYRUS_DATAPACK_DELIVERY_REAL (+ CYRUS_WORLDGEN), CYRUS_CREATURES) and the Mods engine's ENABLE_REAL_GAMEMODS.
 * The GAME_MOD_SYNC job already holds the per-server lock (one job per server at a time).
