type ServerRow = NonNullable<Awaited<ReturnType<typeof loadServer>>>;
const loadServer = (id: string) => db.server.findUnique({ where: { id }, include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true } });
const MC = cyrusConfig().guest.mcBase;
const LOG = `${MC}/logs/latest.log`;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

/** Health facts from a Paper latest.log (pure; moved to lib/cyrus/delivery/bootlog.ts, re-exported here unchanged). */
export { parseBootLog };

function session(server: ServerRow, fs: GuestFs, levelName: string): ServerSession {
  const spec = controlSpec("minecraft");
  const readLog = async () => (await fs.readFile(LOG, 8 * 1024 * 1024))?.toString("utf8") ?? "";
  let preLog: string | null = null;
  const rcon = async (cmd: string) => {
    if (SANDBOX || !spec) return { ok: false as const, error: "no console here" };
    try { const r = await withServerSsh(server, (conn) => runRcon(conn, spec, cmd)); return r.ok ? { ok: true as const, reply: r.response } : { ok: false as const, error: r.error }; }
    catch (e) { return { ok: false as const, error: (e as Error).message }; }
  };
  return {
    fs: fs as unknown as TxnFs, base: MC, levelName, mcVersion: null,
    async baselineErrors() { preLog = await readLog(); return parseBootLog(preLog).errors; },
    async restart() {
      if (SANDBOX) return { ok: true };
      if (!spec) return { ok: false, error: "no control spec for minecraft" };
      const before = preLog ?? (await readLog());
      try {
        const r = await withServerSsh(server, (conn) => sshExec(conn, powerScript(spec, "restart"), 90_000));
        const rc = /NXGP:RC:(\d+)/.exec(r.stdout)?.[1];
        if (/NXGP:UNIT:NONE/.test(r.stdout)) return { ok: false, error: "the game service was not found" };
        if (rc !== "0") return { ok: false, error: `systemctl restart exited ${rc ?? "?"}` };
      } catch (e) { return { ok: false, error: (e as Error).message }; }
      // wait for a NEW log (Paper rotates latest.log at start) that reaches Done, or gives up (health then says so)
      const until = Date.now() + 300_000;
      while (Date.now() < until) {
        await sleep(5000);
        const now = await readLog().catch(() => "");
        if (now && now !== before && (parseBootLog(now).cameUp || /Stopping server|FATAL|Registry loading errors/.test(now))) break;
      }
      preLog = null;
      return { ok: true };
    },
    ...(SANDBOX ? {} : { console: rcon }),
    async health(): Promise<HealthReport> {
      if (SANDBOX) return { real: false, cameUp: false, answered: false, pluginsEnabled: [], errorLines: [], datapacksLoaded: [], evidence: ["sandbox: no real server"] };
      const log = parseBootLog(await readLog());
      const list = await rcon("list");
      const dps = await rcon("datapack list enabled");
      return {
        real: true, cameUp: log.cameUp, answered: list.ok, pluginsEnabled: log.enabled, errorLines: log.errors,
        datapacksLoaded: dps.ok ? [...dps.reply.matchAll(/file\/([A-Za-z0-9_.-]+?\.zip)/g)].map((m) => `file/${m[1]}`) : [],
        evidence: [log.cameUp ? "Done line found" : "no Done line", list.ok ? "answers list" : `list: ${list.ok ? "" : list.error}`],
      };
    },
    close() { (fs as unknown as { close?: () => void }).close?.(); },
  };
}

/** Nxeon's DeliveryHost for one server. */
export function nxeonDeliveryHost(server: ServerRow, ctx: { rootBuildId?: string | null; buildId?: string | null }, env: Record<string, string | undefined> = process.env): DeliveryHost {
  const catalog = loadCatalog();
  const facts = serverFacts(server, "minecraft");
  const mdeps = (fs: TxnFs) => ({ db, catalog, installer: engineManagedInstaller({ env, open: async () => ({ fs: fs as unknown as GuestFs, server: facts }) }) });
  const pluginNameOf = (key: string) => catalog.find((e) => e.key === key)?.pluginName ?? key;
  const cyrusInstaller = engineInstallerFor("minecraft", "cyrus");
  const engineDeps = (fs: TxnFs) => ({ fs: fs as unknown as GuestFs, fetcher: safeFetch, mirror: dbMirrorLookup((sql, ...args) => db.$queryRawUnsafe(sql, ...args)) });
  const store = selectPackStore(env);
  return {
    env,
    async open() {
      const fs: GuestFs = SANDBOX ? new LocalGuestFs(sandboxGuestRoot(server.id)) : await SshGuestFs.open(server);
      const props = (await fs.readFile(`${MC}/server.properties`, 256 * 1024))?.toString("utf8") ?? "";
      const level = /^level-name=([A-Za-z0-9_-]{1,64})\s*$/m.exec(props)?.[1] ?? "world";
      return session(server, fs, level);
    },
    managed: {
      async ensure(a) { const r = await ensureManagedPlugin(mdeps(a.fs), a); return r.ok ? { ok: true, action: r.action, pluginName: pluginNameOf(a.key) } : { ok: false, error: r.error }; },
      async release(a) { const r = await releaseManagedPlugin(mdeps(a.fs), a); return r.ok ? { ok: true, action: r.action } : { ok: false, error: r.error }; },
      snapshot: (serverId) => snapshotServerManaged(db, serverId),
      async restore(_serverId, snap) { try { await restoreServerManaged(db, snap as ManagedSnapshot); return { ok: true }; } catch (e) { return { ok: false, error: (e as Error).message }; } },
    },
    jar: {
      async install({ fs, base, release, previous }) {
        if (!cyrusInstaller || !ctx.rootBuildId) return { ok: false, error: "the Cyrus installer is not available" };
        const gm = await ensureCyrusGameMod(ctx.rootBuildId);
        if (!gm) return { ok: false, error: "this Cyrus mod has no catalogue row" };
        const r = await installOrUpdate(cyrusInstaller, catalogFacts(gm, { targetVersionId: release.modBuildId ?? null }), facts, engineDeps(fs), previous ? "update" : "install");
        if (!r.ok) return { ok: false, error: r.error };
        return { ok: true, target: `${base}/plugins/${r.fileName ?? release.plugin!.jarName}` };
      },
      async remove({ fs }) {
        if (!cyrusInstaller || !ctx.rootBuildId) return { ok: false, error: "the Cyrus installer is not available" };
        const gm = await ensureCyrusGameMod(ctx.rootBuildId);
        if (!gm) return { ok: false, error: "this Cyrus mod has no catalogue row" };
        const r = await engineUninstall(cyrusInstaller, catalogFacts(gm), facts, engineDeps(fs));
        return r.ok ? { ok: true } : { ok: false, error: r.error };
      },
    },
    // Mod Packs: members go through the Mods engine (its state file records them); off unless CYRUS_MODPACK_INSTALL_REAL=1
    modpackPlacer: (fs, _session, packId) => engineMemberPlacer({ fs: fs as unknown as GuestFs, server: facts, packId, env }),
    ...(store.ok ? { packs: { store: store.store, async publish(zip) { const p = await publishPack(store.store, zip, { maxBytes: store.maxBytes }); if (!p.ok) throw new Error(p.error); return { url: p.url }; } } } : {}),
  };
}

/** Nxeon's deps for the host-neutral job body (lib/cyrus/delivery/job.ts). */
export const nxeonDeliveryJobDeps = (env: Record<string, string | undefined> = process.env): DeliveryJobDeps<ServerRow> => ({
  env,
  server: (id) => loadServer(id),
  build: (id) => cyrusDb.modBuild.findUnique({ where: { id } }),
  readJar: (p) => readFile(p).catch(() => null),
  projectForRoot: (root) => projectForRootBuild(root),
  project: (id) => cyrusDb.cyrusProject.findUnique({ where: { id } }),
  // Config Studio (op "config"): the saved settings are re-read from the owner's project in the studio store (never from the payload)
  configRelease: configReleaseDep({ store: prismaStudioStore, source: configSourceOf }),
  datapackAssets: (revisionId) => cyrusDb.cyrusProjectAsset.findMany({ where: { revisionId, kind: "datapack" }, select: { assetKey: true, provenance: true } }),
  host: (server, ctx) => nxeonDeliveryHost(server, ctx, env),
  async storeResult(jobId, result) {
    const cur = await db.job.findUnique({ where: { id: jobId }, select: { payload: true } });
    const prev = (cur?.payload && typeof cur.payload === "object" ? cur.payload : {}) as Record<string, unknown>;
    await db.job.update({ where: { id: jobId }, data: { payload: { ...prev, result: { cyrusDelivery: result } } as Prisma.InputJsonValue } });
  },
  audit: async (userId, action, detail) => { await db.auditLog.create({ data: { userId, action, detail } }); },
  async installRow(u) {
    if (u.kind === "delivered") await db.serverMod.update({ where: { id: u.serverModId }, data: { status: "INSTALLED", versionId: u.buildId, fileName: u.jarName, error: null, targetVersionId: null } });
    else if (u.kind === "removed") await db.serverMod.delete({ where: { id: u.serverModId } });
    else if (u.kind === "restore") await db.serverMod.update({ where: { id: u.serverModId }, data: { status: u.prev.status, versionId: u.prev.versionId, error: u.error, targetVersionId: null } });
    else await db.serverMod.update({ where: { id: u.serverModId }, data: { status: "FAILED", error: u.error, targetVersionId: null } });
  },
  noRetry: (jobId) => noRetry(jobId),
  // the store is per account (NXEON_MODBUILD_DIR/modpacks/<userId>/...): the job opens only the server owner's packs
  async modpack(userId, ref) {
    const zip = await modPackStore.readVersion(userId, ref.packId, ref.versionId).catch(() => null);
    return zip ? openPackArchive(zip, ref) : { ok: false, error: "the Mod Pack version was not found" };
  },
});
const modPackStore = new FsModPackStore();

export async function cyrusDeliveryJob(job: Job): Promise<void> {
  await runDeliveryJob(job, nxeonDeliveryJobDeps());
}

1	// Cyrus R5: the DELIVERY ORCHESTRATOR. Installs / updates / uninstalls one Cyrus mod (plugin jar + resource pack +
2	// data packs + world generation + managed plugins + creatures) or one Mod Pack on ONE server, as one transaction-like
3	// sequence:
4	//   open -> recover check (a left-over journal refuses) -> preflight (server inventory + conflict engine against what is
5	//   already there: blocking refuses, warnings are recorded; release bytes verified; Pack Loader config valid) ->
6	//   [snapshot managed-plugin refs] -> ensure managed plugins (Pack Loader, BetterModel) -> host the pack (immutable URL)
7	//   -> Pack Loader config -> place jar / data packs / creature models (all through the copy-on-write journal) -> delivery
8	//   record -> apply ONLY as the semantics require (restart / minecraft:reload / nothing) -> HEALTH CHECK (answers,
9	//   plugins enabled, no new error lines, data packs loaded, worldgen: really came up) -> BetterModel hand-off (after the
10	//   restart) -> commit.
11	// ANY failure after preflight rolls back to the exact previous state: every journaled file (bytes verified), the
12	// managed-plugin refs (database rows), and, when the server was restarted or reloaded, restarts / reloads it again and
13	// checks that it came up; why is recorded step by step. Mod Packs reuse the same transaction (their unit installer
14	// writes through the same journal), so a pack is still one unit.
15	// OFF unless CYRUS_DELIVERY=1 (and each part behind its existing flag: CYRUS_MANAGED_PLUGINS_REAL,
