44	const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");
45	const sha1 = (b: Buffer) => createHash("sha1").update(b).digest("hex");
46	const errMsg = (e: unknown) => (e instanceof Error ? e.message : String(e)).slice(0, 500);
47	const NS_RE = /^nx_[a-z0-9]{8}$/;
