53	class StepFail extends Error { constructor(readonly step: DeliveryStep, msg: string) { super(msg); } }
54	class Refusal extends Error { constructor(readonly step: DeliveryStep, msg: string, readonly conflicts?: ConflictSummary) { super(msg); } }
