56	export type DeliverOptions = {
57	  /** "now" (default): restart when the change needs one, then health-check. "next_restart": never restart (refused for worldgen/creatures). */
58	  restartPolicy?: "now" | "next_restart";
59	  /** Warning finding ids the user acknowledged (recorded; warnings never block). */
60	  acknowledge?: string[];
61	  /** Fail the health check on new error lines (default true). */
62	  strictLog?: boolean;
63	};
