65	type Txn = {
66	  host: DeliveryHost; serverId: string; session: ServerSession; jfs: JournalFs; steps: StepResult[]; notes: string[];
67	  refsSnap: unknown; refsTouched: boolean; restartAttempted: boolean; reloaded: boolean; baseline: string[];
68	  /** Config Studio: the mod reload command already sent (re-sent after a rollback restores the old file). */
69	  pluginReloaded?: string | null;
70	};
71	type BodyOut = { apply: ApplyInput; expect: HealthExpect; record: DeliveryRecord | null; outcome: DeliveryResult["outcome"]; handoff?: boolean; keptWorldFolders?: string[]; unchanged?: boolean; conflicts?: ConflictSummary };
72	type Prepared = { body: (t: Txn) => Promise<BodyOut>; conflicts?: ConflictSummary; precheckRestart?: { worldgen: boolean; creatures: boolean } };
