74	async function timed<T>(t: { steps: StepResult[]; host: DeliveryHost }, step: DeliveryStep, fn: () => Promise<T>, detail?: (v: T) => string): Promise<T> {
75	  const t0 = Date.now();
76	  try {
77	    t.host.fault?.(step);
78	    const v = await fn();
79	    t.steps.push({ step, status: "ok", ms: Date.now() - t0, detail: detail ? detail(v).slice(0, 400) : "" });
80	    return v;
81	  } catch (e) {
82	    t.steps.push({ step, status: "failed", ms: Date.now() - t0, detail: errMsg(e) });
83	    if (e instanceof Refusal || e instanceof StepFail) throw e;
84	    throw new StepFail(step, errMsg(e));
85	  }
86	}
87	const skip = (t: { steps: StepResult[] }, step: DeliveryStep, detail: string) => t.steps.push({ step, status: "skipped", ms: 0, detail });
