89	/** The shared transaction. `prepare` runs the read-only preflight; its `body` does every mutation through t.jfs. */
90	async function transaction(a: { serverId: string; op: DeliveryResult["op"]; subject: DeliveryResult["subject"]; host: DeliveryHost; label: string; opts: DeliverOptions; prepare: (s: ServerSession, steps: StepResult[]) => Promise<Prepared> }): Promise<DeliveryResult> {
91	  const env = a.host.env ?? process.env;
92	  const now = a.host.now ?? (() => new Date());
93	  const startedAt = now().toISOString();
94	  const steps: StepResult[] = [];
95	  const notes: string[] = [];
96	  const done = (r: Omit<DeliveryResult, "op" | "serverId" | "subject" | "steps" | "notes" | "startedAt" | "finishedAt">): DeliveryResult =>
97	    ({ op: a.op, serverId: a.serverId, subject: a.subject, steps, notes, startedAt, finishedAt: now().toISOString(), ...r });
98	  if (!switches(env).delivery) return done({ ok: false, outcome: "refused", error: "Cyrus delivery is switched off (CYRUS_DELIVERY is not 1); nothing was changed" });
99	
100	  let session: ServerSession;
101	  try { session = await timed({ steps, host: a.host }, "open", () => a.host.open(a.serverId)); }
102	  catch (e) { return done({ ok: false, outcome: "refused", failedStep: "open", error: `the server could not be opened: ${errMsg(e)}` }); }
103	  try {
104	    try {
105	      const left = await timed({ steps, host: a.host }, "recover_check", () => pendingJournals(session.fs), (v) => (v.length ? `left-over journals: ${v.join(", ")}` : "none"));
106	      if (left.length) return done({ ok: false, outcome: "refused", failedStep: "recover_check", error: `a previous delivery to this server did not finish (journal ${left[0]}); an admin must recover it first (recoverJournal) before anything else is delivered` });
107	    } catch (e) { return done({ ok: false, outcome: "refused", failedStep: "recover_check", error: errMsg(e) }); }
108	
109	    let prep: Prepared;
110	    try { prep = await a.prepare(session, steps); }
111	    catch (e) {
112	      const ref = e instanceof Refusal ? e : null;
113	      return done({ ok: false, outcome: "refused", failedStep: ref?.step ?? "preflight", error: errMsg(e), conflicts: ref?.conflicts });
114	    }
115	    if (a.opts.restartPolicy === "next_restart" && prep.precheckRestart && (prep.precheckRestart.worldgen || prep.precheckRestart.creatures)) {
116	      return done({ ok: false, outcome: "refused", failedStep: "preflight", conflicts: prep.conflicts, error: `${prep.precheckRestart.worldgen ? "world generation" : "animated creatures"} must be delivered with a supervised restart (restartPolicy "now"), because a broken pack stops the server at its next start` });
117	    }
118	
119	    const jfs = new JournalFs(session.fs, { label: a.label, base: session.base, passthrough: JOURNAL_PASSTHROUGH, now: now() });
120	    const t: Txn = { host: a.host, serverId: a.serverId, session, jfs, steps, notes, refsSnap: null, refsTouched: false, restartAttempted: false, reloaded: false, baseline: [] };
121	    let out: BodyOut | null = null;
122	    let plan: ApplyPlan | null = null;
123	    let health: HealthVerdict | undefined;
124	    try {
125	      t.refsSnap = await a.host.managed.snapshot(a.serverId);
126	      t.baseline = (await session.baselineErrors?.().catch(() => [] as string[])) ?? [];
127	      out = await prep.body(t);
128	      if (out.unchanged) { await jfs.commit(); return done({ ok: true, outcome: "unchanged", conflicts: prep.conflicts ?? out.conflicts, record: out.record, journalId: jfs.id }); }
129	      plan = planApply(out.apply);
130	      const restartNow = plan.mode === "restart" && a.opts.restartPolicy !== "next_restart";
131	      // apply
132	      await timed(t, "apply", async () => {
133	        if (plan!.mode === "restart" && !restartNow) return;
134	        if (plan!.mode === "restart") { t.restartAttempted = true; const r = await session.restart(); if (!r.ok) throw new Error(`restart failed: ${r.error}`); }
135	        else if (plan!.mode === "reload") {
136	          if (!session.console) { notes.push("the data pack loads on the next restart (this server cannot run console commands)"); return; }
137	          t.reloaded = true;
138	          const r = await session.console(RELOAD_COMMAND);
139	          if (!r.ok) throw new Error(`${RELOAD_COMMAND} failed: ${r.error}`);
140	        }
141	        for (const c of plan!.consoleAfter) if (session.console) await session.console(c).catch(() => null); // the Pack Loader also watches its file
142	        if (plan!.pluginReload) {
143	          if (!session.console) { notes.push("the new settings load at the next restart (this server cannot run console commands)"); return; }
144	          t.pluginReloaded = plan!.pluginReload;
145	          const r = await session.console(plan!.pluginReload);
146	          if (!r.ok) throw new Error(`/${plan!.pluginReload} failed: ${r.error}`);
147	          if (RELOAD_FAILED_RE.test(r.reply)) throw new Error(`/${plan!.pluginReload} did not reload: ${r.reply.slice(0, 300)}`);
148	          const lines = r.reply.split(/\r?\n/).map((l) => l.trim()).filter(Boolean).slice(0, 8);
149	          if (lines.length) notes.push(`/${plan!.pluginReload}: ${lines.join(" | ").slice(0, 400)}`);
150	        }
151	      }, () => `${plan!.mode}${plan!.mode === "restart" && !restartNow ? " (deferred to the next restart)" : ""}${plan!.pluginReload ? ` + /${plan!.pluginReload}` : ""}: ${plan!.reasons.join("; ")}`);
152	      if (plan.mode === "restart" && !restartNow) {
153	        skip(t, "health", "not checked: the change takes effect at the next restart");
154	        await timed(t, "commit", () => jfs.commit());
155	        notes.push("Restart the server to load the change.");
156	        return done({ ok: true, outcome: "pending_restart", conflicts: prep.conflicts ?? out.conflicts, apply: { mode: plan.mode, reasons: plan.reasons, restarted: false, reloaded: false }, record: out.record, keptWorldFolders: out.keptWorldFolders, journalId: jfs.id });
157	      }
158	      // health
159	      if (plan.mode === "none" && !out.expect.plugins.length && !out.expect.datapacks.length) skip(t, "health", "nothing to check: no restart or reload happened");
160	      else {
161	        health = await timed(t, "health", async () => {
162	          const v = judgeHealth(out!.expect, await session.health(out!.expect), a.opts.strictLog === false ? undefined : t.baseline);
163	          if (a.opts.strictLog === false) v.problems = v.problems.filter((p) => !p.startsWith("new error lines"));
164	          v.ok = v.problems.length === 0;
165	          if (!v.ok) throw Object.assign(new Error(v.problems.join("; ")), { verdict: v });
166	          return v;
167	        }, () => "healthy").catch((e) => { health = (e as { verdict?: HealthVerdict }).verdict; throw e; });
168	      }
169	      // BetterModel builds its pack at start: publish it and point the Pack Loader at it (after the restart)
170	      if (out.handoff && plan.mode === "restart") {
171	        await timed(t, "handoff", async () => {
172	          const store = a.host.packs?.store;
173	          if (!store) { notes.push("the BetterModel pack could not be handed off (no pack hosting here); creatures show without their pack"); return "no store"; }
174	          const h = await handoffBetterModelPack({ fs: jfs as unknown as GuestFs, store, base: session.base });
175	          if (!h.ok) throw new Error(`BetterModel pack hand-off: ${h.error}`);
176	          if (session.console) await session.console("nxpacks reload").catch(() => null);
177	          return "handed off";
178	        }, (v) => String(v));
179	      }
180	      await timed(t, "commit", () => jfs.commit());
181	      return done({ ok: true, outcome: out.outcome, conflicts: prep.conflicts ?? out.conflicts, apply: { mode: plan.mode, reasons: plan.reasons, restarted: t.restartAttempted, reloaded: t.reloaded }, health, record: out.record, keptWorldFolders: out.keptWorldFolders, journalId: jfs.id });
182	    } catch (e) {
183	      const failedStep = e instanceof StepFail || e instanceof Refusal ? e.step : "place";
184	      const rb = await rollback(t, plan);
185	      const incomplete = !rb.ok || rb.refs === "failed" || (rb.health !== null && !rb.health.ok);
186	      return done({
187	        ok: false, outcome: incomplete ? "rollback_incomplete" : "rolled_back", failedStep, error: errMsg(e), conflicts: prep.conflicts ?? out?.conflicts,
188	        apply: plan ? { mode: plan.mode, reasons: plan.reasons, restarted: t.restartAttempted, reloaded: t.reloaded } : undefined, health, rollback: rb, record: null, journalId: jfs.id,
189	      });
190	    }
191	  } finally { session.close?.(); }
192	}
