194	/** Undo: files (journal), refs (database), then restart / reload again if the change already reached the server. */
195	async function rollback(t: Txn, plan: ApplyPlan | null): Promise<RollbackReport & { refs: "restored" | "failed" | "unchanged"; restarted: boolean; health: HealthVerdict | null }> {
196	  const t0 = Date.now();
197	  const files = await t.jfs.rollback();
198	  let refs: "restored" | "failed" | "unchanged" = "unchanged";
199	  if (t.refsTouched) {
200	    const r = await t.host.managed.restore(t.serverId, t.refsSnap).catch((e) => ({ ok: false as const, error: errMsg(e) }));
201	    refs = r.ok ? "restored" : "failed";
202	    if (!r.ok) files.mismatches.push(`managed plugin refs: ${r.error}`);
203	  }
204	  t.steps.push({ step: "rollback", status: files.ok && refs !== "failed" ? "ok" : "failed", ms: Date.now() - t0, detail: `${files.restored} restored, ${files.removed} removed${files.mismatches.length ? `; MISMATCHES: ${files.mismatches.slice(0, 3).join(" | ")}` : ""}; refs ${refs}` });
205	  let restarted = false;
206	  let health: HealthVerdict | null = null;
207	  if (t.restartAttempted) {
208	    const t1 = Date.now();
209	    const r = await t.session.restart().catch((e) => ({ ok: false as const, error: errMsg(e) }));
210	    restarted = r.ok;
211	    t.steps.push({ step: "rollback_restart", status: r.ok ? "ok" : "failed", ms: Date.now() - t1, detail: r.ok ? "restarted on the previous state" : `restart after rollback failed: ${(r as { error: string }).error}` });
212	    const t2 = Date.now();
213	    const rep = r.ok ? await t.session.health({ plugins: [], datapacks: [], worldgen: false }).catch(() => null) : null;
214	    health = judgeHealth({ plugins: [], datapacks: [], worldgen: false }, rep, t.baseline);
215	    health.problems = health.problems.filter((p) => !p.startsWith("new error lines")); // the previous state's own log is not ours to judge
216	    health.ok = health.problems.length === 0;
217	    t.steps.push({ step: "rollback_health", status: health.ok ? "ok" : "failed", ms: Date.now() - t2, detail: health.ok ? "the server came up on the previous state" : health.problems.join("; ").slice(0, 400) });
218	  } else if (t.reloaded && t.session.console) {
219	    await t.session.console(RELOAD_COMMAND).catch(() => null);
220	  }
221	  if (!t.restartAttempted && t.pluginReloaded && t.session.console) {
222	    const r = await t.session.console(t.pluginReloaded).catch((e) => ({ ok: false as const, error: errMsg(e) }));
223	    t.steps.push({ step: "rollback", status: r.ok ? "ok" : "failed", ms: 0, detail: r.ok ? `previous settings reloaded with /${t.pluginReloaded}` : `/${t.pluginReloaded} after the rollback failed: ${(r as { error: string }).error}` });
224	  }
225	  void plan;
226	  return { ...files, refs, restarted, health };
227	}
