231	function datapackCandidate(name: string, zip: Buffer, cyrus: ModEntry["cyrus"]): Promise<ModEntry> {
232	  const z = indexZip(zip);
233	  if (!z.ok) throw new Error(`data pack ${name}: ${z.error}`);
234	  const files = z.zip.entries.filter((e) => !e.dir && e.name.startsWith("data/")).map((e) => ({ path: e.name, read: () => { const r = readEntry(z.zip, e); return r.ok ? r.data : null; } }));
235	  const mm = z.zip.entries.find((e) => e.name === "pack.mcmeta");
236	  const mcmeta = mm ? (() => { const r = readEntry(z.zip, mm); return r.ok ? r.data : null; })() : null;
237	  return indexDatapack(name, "candidate", "zip", files, mcmeta).then((d) => datapackEntry(d, "candidate", { cyrus, changed: true }));
238	}
239	
240	function summarize(rep: ReturnType<typeof detectConflicts>, involve: (f: { items: { mod: string }[] }) => boolean): ConflictSummary {
241	  const mine = rep.findings.filter(involve);
242	  return {
243	    blocking: mine.filter((f) => f.severity === "blocking").map((f) => ({ id: f.id, class: f.class, message: f.message })),
244	    warnings: mine.filter((f) => f.severity !== "blocking").map((f) => ({ id: f.id, class: f.class, severity: f.severity, message: f.message })).slice(0, 50),
245	    notChecked: rep.notChecked.slice(0, 30),
246	  };
247	}
248	
249	function verifyRelease(r: ModRelease): string | null {
250	  if (!/^[A-Za-z0-9_-]{1,64}$/.test(r.projectId)) return "bad project id";
251	  if (!NS_RE.test(r.namespace)) return "bad namespace";
252	  if (r.plugin) {
253	    if (!/^[A-Za-z0-9._ -]{1,120}\.jar$/.test(r.plugin.jarName) || r.plugin.jarName.includes("/")) return "bad jar name";
254	    if (sha256(r.plugin.bytes) !== r.plugin.sha256) return "the plugin jar does not match its recorded sha256";
255	  }
256	  if (r.pack?.zip && sha1(r.pack.zip) !== r.pack.sha1) return "the resource pack does not match its recorded sha1";
257	  if (r.pack && !r.pack.zip && !(r.pack.url && /^https:\/\//.test(r.pack.url))) return "the resource pack has neither bytes nor an https URL";
258	  for (const d of r.datapacks) {
259	    if (!/^[a-z0-9_-]{1,40}$/.test(d.name)) return `bad data pack name ${d.name}`;
260	    if (sha256(d.zip) !== d.sha256) return `data pack ${d.name} does not match its recorded sha256`;
261	    if (d.worldgen && d.apply !== "restart") return `data pack ${d.name} has world generation and must be applied with a restart`;
262	  }
263	  return null;
264	}
