268	/** Install a revision of a Cyrus mod, or update the one already delivered (same project). */
269	export async function deliverMod(serverId: string, release: ModRelease, host: DeliveryHost, opts: DeliverOptions = {}): Promise<DeliveryResult> {
270	  const env = host.env ?? process.env;
271	  const sw = switches(env);
272	  let op: DeliveryResult["op"] = "install";
273	  const result = await transaction({
274	    serverId, op, subject: { projectId: release.projectId, revisionId: release.revisionId }, host, label: `deliver-${release.projectId}`, opts,
275	    prepare: async (session, steps) => {
276	      const ctx = { steps, host };
277	      return timed(ctx, "preflight", async () => {
278	        const bad = verifyRelease(release);
279	        if (bad) throw new Refusal("preflight", `the mod version is not deliverable: ${bad}; nothing was changed`);
280	        const notes: string[] = [];
281	        // what this delivery may carry (each part behind its own switch; off = left out with a note)
282	        const datapacks = release.datapacks.filter((d) => {
283	          if (!sw.datapacks) { notes.push(`data pack ${d.name} was not delivered: data pack delivery is switched off`); return false; }
284	          if (d.worldgen && !sw.worldgen) { notes.push(`data pack ${d.name} was not delivered: world generation is switched off`); return false; }
285	          return true;
286	        });
287	        const pack = release.pack && sw.managed && (release.pack.url || host.packs) ? release.pack : null;
288	        if (release.pack && !pack) notes.push(sw.managed ? "the custom resource pack was not delivered: pack hosting is not available here" : "the custom resource pack was not delivered: managed plugins (the Pack Loader) are switched off");
289	        const creatures = sw.creatures ? release.creatures : [];
290	        if (release.creatures.length && !creatures.length) notes.push("animated creatures were not delivered: creature delivery is switched off");
291	        const compiled = creatures.length ? compileStoredCreatures(release.namespace, creatures) : { ok: true as const, files: [] };
292	        if (!compiled.ok) throw new Refusal("preflight", `${compiled.error}; nothing was changed`);
293	        if (!release.plugin && !datapacks.length && !pack && !compiled.files.length) throw new Refusal("preflight", "nothing in this version can be delivered with the current switches; nothing was changed");
294	        const prev = readRecord(await session.fs.readFile(recordPath(release.projectId), 1024 * 1024));
295	        op = prev ? "update" : "install";
296	        // inventory + conflicts against what the server already runs (our own previous files excluded)
297	        const ro = host.readOnly?.(session) ?? session.fs;
298	        const inv = await scanServer(ro, { base: session.base });
299	        const own = new Set([prev?.jar?.target, ...(prev?.datapacks.map((d) => d.target) ?? [])].filter(Boolean).map((p) => p!.slice(session.base.length + 1)));
300	        const { mods, ctx: cctx } = inventoryEntries(inv, { exclude: (p) => own.has(p) || [...own].some((o) => o.endsWith(`/${p}`) || p.endsWith(o)) });
301	        const cyrus = { namespace: release.namespace, projectId: release.projectId };
302	        const cands: ModEntry[] = [];
303	        if (release.plugin) cands.push(candidateJar(release.plugin.jarName, release.plugin.bytes, { id: `candidate:${release.plugin.jarName}`, cyrus }));
304	        for (const d of datapacks) cands.push(await datapackCandidate(datapackFile(release.namespace, d.name).replace(/\.zip$/, ""), d.zip, cyrus));
305	        const rep = detectConflicts([...cands, ...mods], { ...cctx, mcVersion: cctx.mcVersion ?? session.mcVersion ?? release.mcVersion });
306	        const candIds = new Set(cands.map((c) => c.id));
307	        const conflicts = summarize(rep, (f) => f.items.some((i) => candIds.has(i.mod)));
308	        if (conflicts.blocking.length) throw new Refusal("preflight", `blocked by ${conflicts.blocking.length} conflict(s) with what is already on the server: ${conflicts.blocking.map((b) => b.message).join(" | ").slice(0, 500)}; nothing was changed`, conflicts);
309	        // the Pack Loader config must be valid before we touch anything
310	        if (pack || prev?.packLoaderIds.length) {
311	          const cur = await readLoaderConfig(session.fs as unknown as GuestFs, session.base);
