export const SEVERITIES = ["blocking", "warn", "info"] as const;
export type Severity = (typeof SEVERITIES)[number];

export const CONFLICT_CLASSES = [
  "plugin.duplicate_name", "plugin.duplicate_main",
  "command.label_collision", "command.alias_collision", "command.vanilla_override",
  "permission.duplicate", "permission.default_mismatch",
  "dependency.missing", "dependency.cycle", "dependency.loadbefore_cycle",
  "platform.api_version", "platform.java", "platform.folia", "platform.item_model_version",
  "event.overlap", "event.monitor_mutation",
  "key.namespacedkey", "key.namespace_foreign",
  "item.custom_model_data", "item.item_model",
  "recipe.key",
  "sound.key", "sound.vanilla_replace",
  "resource.single_owner",
  "datapack.tag_replace", "datapack.vanilla_override", "datapack.id_collision", "datapack.function_tag_order",
  // Cyrus R4 worldgen: world generation ids defined twice / vanilla world generation replaced
  "datapack.worldgen_collision", "datapack.worldgen_override",
  "rp.whole_file", "rp.shader", "rp.font_codepoint", "rp.sounds_json", "rp.lang", "rp.atlas", "rp.existing_owner",
  "budget.display_entities", "budget.tasks", "budget.pack_size",
  "policy.server_jar", "safety.jar_flags",
] as const;
export type ConflictClass = (typeof CONFLICT_CLASSES)[number];

export const RESOLUTION_KINDS = ["none", "reserved_namespace", "alias_rewrite", "stacking_order", "merge", "load_order", "remove_one", "upgrade_or_replace", "user_decision"] as const;
export type ResolutionKind = (typeof RESOLUTION_KINDS)[number];
/** `auto` = the Mod Pack builder applies it by itself (merge, stacking order, pack.mcmeta); otherwise it is a proposal. */
export type Resolution = { kind: ResolutionKind; auto: boolean; text: string; proposal?: Record<string, unknown> };

export type FindingItem = { mod: string; label: string; evidence: string };
export type Finding = {
  /** Stable: same class + subject + mods always gives the same id (used to acknowledge a warn). */
  id: string;
  class: ConflictClass;
  severity: Severity;
  subject: string;
  items: FindingItem[];
  message: string;
  resolution: Resolution;
};

/** One resource pack's file index (see ./resourcepack.ts indexResourcePack). JSON is kept only for files the engine merges or inspects. */
export type ResourcePackIndex = { name: string; bytes: number; files: { path: string; sha1: string }[]; json: Record<string, unknown>; issues: string[] };

/** A mod as the conflict engine sees it: a server inventory entry and/or a new candidate. */
export type ModEntry = {
  /** Unique within one check, e.g. `server:plugins/Foo.jar` or `member:<id>`. */
  id: string;
  label: string;
  kind: "plugin" | "datapack" | "resourcepack" | "serverjar";
  origin: "server" | "candidate";
  /** Built by Cyrus: its reserved project namespace (`nx_<8>`). */
  cyrus: { namespace: string; projectId?: string } | null;
  /** New or changed in this composition (drives differential boots). */
  changed?: boolean;
  plugin?: { descriptor: PluginDescriptor | null; bytecode: BytecodeSummary | null; jarFlags?: JarFlags; sha256?: string };
  datapack?: DatapackIndex;
  resourcePack?: ResourcePackIndex;
  /** Declared budgets (from the mod's spec); inferred bytecode sites are used when absent, marked as estimates. */
  budgets?: { displayEntities?: number; repeatingTasks?: number; packBytes?: number };
};

export type ConflictContext = {
  /** Server Minecraft version (registry id) when known. */
  mcVersion?: string | null;
  javaRelease?: number | null;
  software?: string | null;
  /** Existing resource-pack owners on the server (from the inventory). */
  packOwners?: ResourcePackOwner[];
  /** true for a Mod Pack build: server jars, unsafe jars and unresolved blocking findings refuse the pack. */
  modPack?: boolean;
  budgets?: { maxDisplayEntities?: number; maxRepeatingTasks?: number; maxPackBytes?: number };
};

export type ConflictReport = {
  engine: "cyrus-conflicts-1";
  mods: { id: string; label: string; kind: ModEntry["kind"]; origin: ModEntry["origin"]; cyrus: boolean }[];
  findings: Finding[];
  counts: Record<Severity, number>;
  blocking: boolean;
  /** Classes (per mod) that could not be checked for lack of data. Not checked is never reported as clean. */
  notChecked: string[];
};
