  const desc = (m: ModEntry) => m.plugin?.descriptor ?? null;
  const bc = (m: ModEntry) => m.plugin?.bytecode ?? null;
  for (const m of plugins) {
    if (!desc(m)) notChecked.push(`${m.label}: no plugin descriptor, so names, commands, permissions and dependencies were not checked`);
    if (!bc(m)) notChecked.push(`${m.label}: no bytecode summary, so events, keys, item models, recipes, sounds and single-owner resources were not checked`);
  }

