/**
 * Mock-driven END-TO-END of the Cyrus mod lifecycle against a THROWAWAY Postgres and the
 * SANDBOX guest filesystem (lib/mods/guest-fs.ts LocalGuestFs: a temp folder stands in for the
 * server's disk). Real engine, real worker functions (GAME_MOD_SYNC, the lifecycle sweeps), real
 * DB writes; no SSH, no network, no email (a fake mailer records what would be sent).
 *
 * Opt-in and fail-closed: runs only when CYRUS_LIFECYCLE_DB_TEST=1 and DATABASE_URL is a node-2
 * agent database (127.0.0.1:5433/wt_*). Schema first: `devhost db push`.
 *   devhost run --lock -- env CYRUS_LIFECYCLE_DB_TEST=1 npx tsx --test test/cyrus-lifecycle-db.test.ts
 */
const url = process.env.DATABASE_URL ?? "";
const safe = process.env.CYRUS_LIFECYCLE_DB_TEST === "1" && /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:5433\/wt_[a-z0-9_]+(\?.*)?$/.test(url);
const skip = safe ? false : "set CYRUS_LIFECYCLE_DB_TEST=1 with a node-2 throwaway DATABASE_URL to run";

// Same idempotent `server-only` shim as test/chat-agent-tools.test.ts (the worker's import graph
// reaches modules that open with `import "server-only"`, a no-op on the server).
if (safe) {
  const shimDir = path.join(import.meta.dirname, "..", "node_modules", "server-only");
  const OUR_SHIM = "module.exports = {};\n";
  if (!existsSync(path.join(shimDir, "index.js")) || readFileSync(path.join(shimDir, "index.js"), "utf8") !== OUR_SHIM) {
    mkdirSync(shimDir, { recursive: true });
    writeFileSync(path.join(shimDir, "package.json"), '{"name":"server-only","version":"0.0.0","main":"index.js","browser":"index.js"}\n');
    writeFileSync(path.join(shimDir, "index.js"), OUR_SHIM);
  }
}

