async function mkBuild(id: string, n: number, mcVersion: string, extra: Record<string, unknown> = {}) {
  const bytes = writeZip([
    { name: "plugin.yml", data: Buffer.from(`name: CoinShop\nversion: 1.${n - 1}.0\nmain: com.nxeon.CoinShop\napi-version: '1.21'\n`) },
    { name: "com/nxeon/CoinShop.class", data: Buffer.from(`fake-class-${id}`) },
  ]);
  const jarPath = path.join(jarDir, `${id}.jar`);

  const jarPath = path.join(jarDir, `${id}.jar`);
  writeFileSync(jarPath, bytes);
  return db.modBuild.create({
    data: {
      id, userId: ids.user, prompt: "A coin shop with /pay and a chest menu", status: "succeeded", mcVersion, pluginName: "CoinShop", version: `1.${n - 1}.0`,
      rootBuildId: `${uniq}a`, baseBuildId: n > 1 ? `${uniq}a` : null, jarName: `CoinShop-1.${n - 1}.0.jar`, jarPath, jarSize: bytes.length, jarSha256: createHash("sha256").update(bytes).digest("hex"),
