      createdAt: new Date(Date.now() - (10 - n) * 60_000), finishedAt: new Date(), ...extra,
    } as never,
  });
}

/** Stand-in for the worker loop: run the queued GAME_MOD_SYNC and mark it DONE. */
async function runJobs() {
  const jobs = await db.job.findMany({ where: { serverId: ids.server, status: "QUEUED", type: "GAME_MOD_SYNC" }, orderBy: { createdAt: "asc" } });
  for (const j of jobs) {
    await W.gameModSync(j);
    await db.job.update({ where: { id: j.id }, data: { status: "DONE" } });
  }
  return jobs.length;
}
