// Worker glue for Cyrus pack delivery (SERVER ONLY): called by worker/game-mods.ts after the Mods engine changed a
// Cyrus mod on a server, with the guest connection it already holds. With CYRUS_MANAGED_PLUGINS_REAL unset this
// returns null BEFORE any database read or server access, so today's behaviour is unchanged.
import { cyrusDb as db } from "../db";
import type { HostGuestFs as GuestFs } from "../host/types";
import type { HostServerFacts as ServerFacts } from "../host/types";
import { loadCatalog } from "../managed/catalog";
import { engineManagedInstaller } from "../managed/installer";
import { projectForRootBuild } from "../engine-core/store";
import { deliverBuildPack, packIdentOf, PACK_DELIVERY_FLAG, removeBuildPack, type DeliverDeps, type DeliverResult } from "./deliver";
import { creaturesSwitchedOn, deliverCreatures, removeCreatures, type StoredCreature } from "../creature/deliver";
import { readBuildAssets } from "./sync";

export async function afterCyrusModChange(a: { serverId: string; versionId: string | null; op: "install" | "update" | "remove"; fs: GuestFs; facts: ServerFacts; env?: Record<string, string | undefined> }): Promise<DeliverResult | null> {
  const env = a.env ?? process.env;
  if (env[PACK_DELIVERY_FLAG] !== "1" || !a.versionId) return null;
  const build = await db.modBuild.findUnique({ where: { id: a.versionId }, select: { id: true, mcVersion: true, result: true, rootBuildId: true } });
  if (!build) return null;
  const deps: DeliverDeps = {
    fs: a.fs, env,
    managed: { db, catalog: loadCatalog(), installer: engineManagedInstaller({ env, open: async () => ({ fs: a.fs, server: a.facts }) }) },
  };
  const ident = packIdentOf(build) ?? (await projectForRootBuild(build.rootBuildId ?? build.id).then((p) => (p ? { namespace: p.namespace, projectId: p.id } : null)));
  let r: DeliverResult | null;
  if (a.op === "remove") r = ident ? await removeBuildPack(a.serverId, ident, deps) : null;
  else {
    r = await deliverBuildPack(a.serverId, build, deps);
    // A version without a pack replaced one with a pack: drop the stale entry.
    if (r.ok && r.action === "no_pack" && ident) r = await removeBuildPack(a.serverId, ident, deps);
  }
  // Cyrus R3 creatures: BetterModel + the compiled models. Only with CYRUS_CREATURES=1 as well (fail closed).
  if (creaturesSwitchedOn(env) && ident) {
    const stored = (readBuildAssets(build.result)?.creatures ?? []) as StoredCreature[];
    const c = a.op === "remove"
      ? await removeCreatures({ serverId: a.serverId, mcVersion: build.mcVersion, ...ident }, { managed: deps.managed, fs: a.fs, env })
      : await deliverCreatures({ serverId: a.serverId, mcVersion: build.mcVersion, ...ident, creatures: stored }, { managed: deps.managed, fs: a.fs, env });
    if (!c.ok) return r && r.ok ? { ...r, notes: [...r.notes, `animated creatures not delivered: ${c.error}`] } : { ok: false, error: `animated creatures not delivered: ${c.error}` };
    if (r && !r.ok) return { ok: false, error: `${r.error}${c.restartRequired ? " (animated creatures were delivered; restart the server)" : ""}` };
    const notes = [...(r && r.ok ? r.notes : []), ...c.notes];
    const base: DeliverResult = r && r.ok ? r : { ok: true, action: "no_pack", wrote: false, notes: [] };
    // restart needed for a new BetterModel or changed models: reported through `loader` like a newly placed plugin
    return { ...(base as Extract<DeliverResult, { ok: true }>), notes, ...(c.restartRequired ? { loader: "installed" } : {}) };
  }
  return r;
}

// Cyrus mods on ONE server: what the Mods tab shows next to a Cyrus row
// (installed version, newer version, history with notes) and the pre-engine
// builder installs it can start tracking. Server-only (DB), no next/* imports.
import type { ModBuild } from "@prisma/client";
import { db } from "../db";
import { cyrusDb } from "../cyrus/db";
import { CYRUS_SOURCE } from "../mods/installers/cyrus";
import { buildModDoc, currentVersion, succeededVersions, versionLabel } from "./doc";
import { packageVersionFor } from "./registry";

export type CyrusRowInfo = {
  rootBuildId: string;
  /** The build on the server now (ServerMod.versionId), when known. */
  installedBuildId: string | null;
  installedLabel: string | null;
  /** The chain's current version (the creator's restored head, else the newest). */
  latestBuildId: string;
  latestLabel: string;
  /** Package version string of the latest (what ServerMod.version would read after updating). */
  latestPackageVersion: string;
  updateAvailable: boolean;
  versionCount: number;
  /** NxLabs page slug (the page exists for every finished chain). */
  pageSlug: string | null;
};

export type CyrusVersionRow = {
  buildId: string;
  label: string;
  version: string | null;
  mcVersion: string;
  at: string;
  notes: string;
  request: string;
  installed: boolean;
  latest: boolean;
  safety: "pass" | "warn" | "block" | null;
};

async function chainsFor(roots: string[]): Promise<Map<string, ModBuild[]>> {
  const rows = roots.length ? await cyrusDb.modBuild.findMany({ where: { OR: [{ id: { in: roots } }, { rootBuildId: { in: roots } }] }, orderBy: { createdAt: "asc" } }) : [];
  const out = new Map<string, ModBuild[]>();
  for (const b of rows) {
    const r = b.rootBuildId ?? b.id;
    out.set(r, [...(out.get(r) ?? []), b]);
  }
  return out;
}

/** Per-ServerMod Cyrus facts for the rows that are Cyrus mods (keyed by GameMod id). */
export async function cyrusInfoForRows(rows: { modId: string; versionId: string | null; mod: { source: string; sourceId: string | null } }[]): Promise<Map<string, CyrusRowInfo>> {
  const cy = rows.filter((r) => r.mod.source === CYRUS_SOURCE && r.mod.sourceId);
  const out = new Map<string, CyrusRowInfo>();
  if (!cy.length) return out;
  const roots = [...new Set(cy.map((r) => r.mod.sourceId!))];
  const [chains, pages] = await Promise.all([
    chainsFor(roots),
    cyrusDb.cyrusModPage.findMany({ where: { rootBuildId: { in: roots } }, select: { rootBuildId: true, slug: true } }),
  ]);
  for (const r of cy) {
    const chain = chains.get(r.mod.sourceId!) ?? [];
    const ok = succeededVersions(chain);
    const cur = currentVersion(chain);
    if (!cur) continue;
    const idx = (id: string | null) => ok.findIndex((b) => b.id === id);
    const label = (id: string | null) => {
      const i = idx(id);
      return i < 0 ? null : versionLabel({ n: i + 1, version: ok[i].version });
    };
    out.set(r.modId, {
      rootBuildId: r.mod.sourceId!,
      installedBuildId: r.versionId,
      installedLabel: label(r.versionId),
      latestBuildId: cur.id,
      latestLabel: label(cur.id) ?? "latest",
      latestPackageVersion: packageVersionFor(cur, chain),
      updateAvailable: !!r.versionId && r.versionId !== cur.id,
      versionCount: ok.length,
      pageSlug: pages.find((p) => p.rootBuildId === r.mod.sourceId)?.slug ?? null,
    });
  }
  return out;
}

/** Version history of a Cyrus mod with release notes, newest first, marked against what's on the server. */
export async function cyrusVersionHistory(rootBuildId: string, installedBuildId: string | null): Promise<CyrusVersionRow[]> {
  const chain = (await chainsFor([rootBuildId])).get(rootBuildId) ?? [];
  const doc = buildModDoc(chain);
  if (!doc) return [];
  return doc.versions.map((v) => ({
    buildId: v.buildId,
    label: versionLabel(v),
    version: v.version,
    mcVersion: v.mcVersion,
    at: v.at,
    notes: v.notes,
    request: v.request,
    installed: v.buildId === installedBuildId,
    latest: v.buildId === doc.currentBuildId,
    safety: v.safety,
  }));
}

export type UntrackedCyrus = { buildId: string; name: string; version: string | null; at: string };

/**
 * Builds a pre-engine builder install put on this server that the Mods tab
 * can't manage yet (no ServerMod row): newest per chain.
 */
export async function untrackedCyrusInstalls(serverId: string, userId: string): Promise<UntrackedCyrus[]> {
  const builds = await cyrusDb.modBuild.findMany({ where: { userId, status: "succeeded" }, orderBy: { createdAt: "desc" }, take: 200 });
  const here = builds.filter((b) => (b.lastInstall as { serverId?: string } | null)?.serverId === serverId);
  if (!here.length) return [];
  const tracked = new Set(
    (await db.serverMod.findMany({ where: { serverId, mod: { source: CYRUS_SOURCE } }, select: { mod: { select: { sourceId: true } } } })).map((r) => r.mod.sourceId),
  );
  const seen = new Set<string>();
  const out: UntrackedCyrus[] = [];
  for (const b of here) {
    const root = b.rootBuildId ?? b.id;
    if (tracked.has(root) || seen.has(root)) continue;
    seen.add(root);
    out.push({ buildId: b.id, name: b.pluginName ?? "Cyrus mod", version: b.version, at: ((b.lastInstall as { at?: string }).at ?? b.createdAt.toISOString()) });
  }
  return out;
}
