/** Put a published community mod (or one of its versions) on one of YOUR servers, through the mods engine. */
export async function installCommunityMod(slug: string, buildId: string | null, serverId: string): R<{ serverName: string; jobId: string }> {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const page = await pageBySlug(slug, user);
  if (!page) return NF;
  if (page.userId !== user.id && (page.visibility !== "PUBLIC" || page.hiddenAt)) return NF;
  if (typeof serverId !== "string" || !ID_RE.test(serverId)) return { error: "Pick a server." };
  const chain = await loadChain(page.rootBuildId);
  const ok = succeededVersions(chain);
  const b = buildId ? ok.find((x) => x.id === buildId) : currentVersion(chain);
  if (!b || !b.jarPath) return { error: "That version has no plugin file." };
  const servers = await modBuilderServers(user.id);
  const facts = servers.find((s) => s.id === serverId);
  if (!facts) return { error: "That server isn't one of your Minecraft servers." };
  if (!facts.compatible) return { error: facts.reason || "That server can't take this plugin." };
  if (!SANDBOX && process.env.ENABLE_REAL_GAMEMODS !== "1") return { error: "One-click mod changes are paused right now, so nothing was installed." };
  const gm = await ensureCyrusGameMod(page.rootBuildId, chain);
  if (!gm) return { error: "This mod has no finished version yet." };
  const existing = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId: gm.id } } });
  if (existing?.status === "DISABLED") return { error: `${gm.name} is switched off on ${facts.name}. Switch it on in the server's Mods tab first.` };
  if (existing && !["INSTALLED", "FAILED", "REMOVED"].includes(existing.status)) return { error: `${gm.name} is busy on that server. Try again in a moment.` };
  if (existing?.status === "INSTALLED" && existing.versionId === b.id) return { error: `That version is already on ${facts.name}.` };
  const q = await enqueueModOp(serverId, gm.id, existing?.status === "INSTALLED" ? "update" : "install", { userId: user.id, slug: gm.slug }, { targetVersionId: b.id });
  if (!q.ok) return { error: q.error };
  await audit(user.id, "cyrusmods.install", `${page.slug} ${b.id} -> ${serverId}`);
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true, serverName: facts.name, jobId: q.jobId };
}

