export async function switchCyrusVersion(serverId: string, modId: string, buildId: string): Promise<{ ok?: true; error?: string; jobId?: string }> {
  let ctx;
  try {
    ctx = await ownedCyrusRow(serverId, modId);
  } catch {
    return { error: "Not found." };
  }
  const { user, server, row, rootBuildId } = ctx;
  if (familyFor(server) !== "minecraft") return { error: "Not found." };
  if (server.status !== "RUNNING") return { error: "Start the server's VM first — mods are changed on the running server." };
  if (!SANDBOX && process.env.ENABLE_REAL_GAMEMODS !== "1") return { error: "One-click mod changes are paused right now, so nothing was queued." };
  if (row.status !== "INSTALLED") return { error: row.status === "DISABLED" ? `${row.mod.name} is switched off — switch it on first.` : `${row.mod.name} is busy right now.` };
  if (typeof buildId !== "string" || !/^[A-Za-z0-9_-]{1,64}$/.test(buildId)) return { error: "Pick a version." };
  if (row.versionId === buildId) return { error: "That version is already on the server." };
  const b = await cyrusDb.modBuild.findUnique({ where: { id: buildId } });
  if (!b || (b.rootBuildId ?? b.id) !== rootBuildId || b.status !== "succeeded" || !b.jarPath) return { error: "That isn't a finished version of this mod." };
  if (b.userId !== server.userId && !(await publicInstallAllowed(b, server.userId))) return { error: "That version isn't published, so it can't go on this server." };
  const r = await enqueueModOp(serverId, modId, "update", { userId: user.id, slug: row.mod.slug }, { targetVersionId: buildId });
  if (!r.ok) return { error: r.error };
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true, jobId: r.jobId };
}

