/** Update every Cyrus mod with a newer version on this server, in ONE job (config kept, each backed up). */
export async function updateAllCyrusMods(serverId: string): Promise<{ ok?: true; error?: string; count?: number }> {
  let ctx;
  try {
    ctx = await ownedCyrusRows(serverId);
  } catch {
    return { error: "Not found." };
  }
  const { user, server } = ctx;
  if (!live()) return { error: "One-click mod changes are paused right now, so nothing was queued." };
  if (server.status !== "RUNNING") return { error: "Start the server's VM first." };
  const rows = (await lifecycleForServer(serverId)).filter((r) => r.updateAvailable && r.latestBuildId && r.view.state !== "disabled" && !["installing", "updating", "enabling", "disabling", "removing", "failed"].includes(r.view.state));
  if (!rows.length) return { error: "Every Cyrus mod here is on its newest version." };
  // Published versions only for other creators' mods (re-checked by the engine's jar source too).
  const targets: { modId: string; buildId: string; slug: string }[] = [];
  for (const r of rows.slice(0, 25)) {
    const b = await cyrusDb.modBuild.findUnique({ where: { id: r.latestBuildId! } });
    if (!b || !(await publicInstallAllowed(b, server.userId))) continue;
    const gm = await db.gameMod.findUnique({ where: { id: r.modId }, select: { slug: true } });
    targets.push({ modId: r.modId, buildId: b.id, slug: gm?.slug ?? r.modId });
  }
  if (!targets.length) return { error: "No update can be applied right now." };
  const q = await withServerJobLock(serverId, async (tx) => {
    const inflight = await tx.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
    if (inflight > 0) return { ok: false as const, error: "Another operation is already running on this server. Try again when it finishes." };
    const cur = await tx.serverMod.findMany({ where: { serverId, modId: { in: targets.map((t) => t.modId) } }, select: { modId: true, status: true } });
    if (cur.some((c) => c.status !== "INSTALLED")) return { ok: false as const, error: "A mod changed while you were looking. Refresh and try again." };
    for (const t of targets) await tx.serverMod.update({ where: { serverId_modId: { serverId, modId: t.modId } }, data: { status: "UPDATING", error: null, targetVersionId: t.buildId } });
    const job = await tx.job.create({ data: { type: "GAME_MOD_SYNC", serverId, payload: { ops: targets.map((t) => ({ modId: t.modId, op: "update" })), batch: true, cyrusUpdateAll: true } }, select: { id: true } });
    return { ok: true as const, jobId: job.id };
  });
  if (!q.ok) return { error: q.error };
  await db.auditLog.createMany({ data: targets.map((t) => ({ userId: user.id, action: "gameserver.mod.update", detail: `${serverId} mod=${t.slug} version=${t.buildId} batch=${q.jobId} cyrus-update-all` })) }).catch(() => {});
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true, count: targets.length };
}

// Cyrus mod capabilities (networking + AI): types, validation, consent summary and the
// install gate. Pure and client-safe.
//
// A mod may only use the network through the Nxeon wrapper, with every host declared in the
// mod's `nx-capabilities.yml`. The build service validates the manifest with the same rules
// (services/modbuilder/capabilities.js); both read services/modbuilder/rules/net-policy.json,
// and test/cyrus-capabilities.test.ts checks the two implementations agree.
// Design: /root/agent-notes/cyrus-v6/capabilities/DESIGN.md. Default OFF
// (setting `cyrus_mod_networking_enabled`).
import POLICY from "../../services/modbuilder/rules/net-policy.json";

export const NET_POLICY_VERSION: string = POLICY.version;
export const MANIFEST_FILE = "nx-capabilities.yml";

export type PlayerDataCategory = "names" | "chat" | "ip";
export const PLAYER_DATA_CATEGORIES = POLICY.playerData as PlayerDataCategory[];
export const PLAYER_DATA_LABEL: Record<PlayerDataCategory, string> = {
  names: "player names and IDs",
  chat: "chat messages",
  ip: "IP addresses",
};

export type CapabilityHost = { host: string; purpose: string };
export type CapabilitySecret = { name: string; host: string; header?: string; url?: true; description: string };
export type CyrusCapabilities = {
  version: 1;
  network: { hosts: CapabilityHost[]; playerData: PlayerDataCategory[]; maxResponseKiB: number } | null;
  secrets: CapabilitySecret[];
  /** May call the Nxeon AI gateway (metered in the server owner's Cyrus tokens, off until they enable it). */
  ai: boolean;
  policy: string;
  sha256: string;
};

export type ValidationResult = { ok: true; problems: []; manifest: CyrusCapabilities } | { ok: false; problems: string[]; manifest: null };

const DENIED: [string, string][] = [];
for (const [reason, list] of Object.entries(POLICY.deniedSuffixes as Record<string, string[]>)) for (const s of list) DENIED.push([s, reason]);
const LABEL = /^(?!-)[a-z0-9-]{1,63}(?<!-)$/;

/** Why a hostname may not be declared, or null when it may (same wording as the service). */
export function hostProblem(h: unknown): string | null {
  if (typeof h !== "string" || !h) return "is empty";
  if (h !== h.trim() || /\s/.test(h)) return "contains spaces";
  if (/[A-Z]/.test(h)) return "must be lower case";
  if (h.includes("*")) return "must be one exact name (no wildcards)";
  if (h.includes(":") || h.includes("[")) return "must be a name without a port or IP address";
  if (h.includes("/") || h.includes("@")) return "must be a bare hostname (no scheme, path or user)";
